declare
  changes jsonb := $quality_data$[{"id": "885461b6-4e1c-45ac-aa61-3f90b9c49e34", "public_path": "/receta-buddha-bowl", "language": "es", "before": {"seo": {"faq": [{"a": "Sí, tal como está escrita es vegetariana y vegana: toda la proteína viene del tofu y los frijoles negros, sin ningún ingrediente de origen animal.", "q": "¿El Buddha Bowl es una receta vegana?"}, {"a": "Sí. Cocina el arroz, marina y hornea el tofu, y cocina el brócoli al vapor hasta 3 días antes, guardando cada uno por separado en el refrigerador. Arma el bowl con el aguacate justo antes de servir.", "q": "¿Puedo preparar los componentes con anticipación?"}, {"a": "Garbanzos asados con especias, edamame o tempeh son buenas alternativas si no tienes tofu o prefieres otra fuente de proteína vegetal.", "q": "¿Qué puedo usar en lugar de tofu?"}, {"a": "Sécalo bien antes de marinarlo y hornéalo en una sola capa, sin amontonar los cubos, a 200°C durante 20-25 minutos, volteándolos a la mitad de la cocción.", "q": "¿Cómo evito que el tofu quede blando en lugar de dorado?"}], "title": "Buddha Bowl: receta fácil y saludable | Manual de Cocina", "robots": "index,follow", "description": "Buddha Bowl con arroz integral, frijoles negros, brócoli, tofu horneado, aguacate y verduras frescas. Un plato completo y nutritivo."}, "ingredients": [{"name": "1 taza de brócoli en floretes", "unit": "Taza", "amount": "1"}, {"name": "Frijoles negros cocidos", "unit": "Taza", "amount": "1"}, {"name": "Arroz integral", "unit": "Taza", "amount": "1"}, {"name": "Zanahorias ralladas", "unit": "Taza", "amount": "1/2"}, {"name": "Tomates cherry cortados a la mitad", "unit": "Taza", "amount": "1/2"}, {"name": "Aguacate en cubos", "unit": "Taza", "amount": "1/2"}, {"name": "Tofu marinado y horneado", "unit": "Taza", "amount": "1/2"}, {"name": "Semillas de sésamo tostada", "unit": "Cucharada", "amount": "1"}]}, "after": {"seo": {"faq": [{"q": "¿Cómo consigo que el tofu se dore?", "a": "Sécalo bien y reparte los cubos en una sola capa sobre la bandeja. Si se amontonan, retienen vapor y cuesta más dorarlos."}, {"q": "¿Puedo organizar los componentes con antelación?", "a": "Sí. Guarda el arroz, los frijoles, el tofu y las verduras por separado en la nevera; corta el aguacate y monta el bowl al servir."}, {"q": "¿Cómo mantengo la receta vegana?", "a": "Usa tofu y frijoles como indica la receta y comprueba que la marinada no lleve miel, lácteos ni otros ingredientes de origen animal."}], "title": "Buddha Bowl: receta fácil y saludable | Manual de Cocina", "robots": "index,follow", "description": "Buddha Bowl con arroz integral, frijoles negros, brócoli, tofu horneado, aguacate y verduras frescas. Un plato completo y nutritivo."}, "ingredients": [{"name": "Brócoli en floretes", "unit": "Taza", "amount": "1"}, {"name": "Frijoles negros cocidos", "unit": "Taza", "amount": "1"}, {"name": "Arroz integral", "unit": "Taza", "amount": "1"}, {"name": "Zanahorias ralladas", "unit": "Taza", "amount": "1/2"}, {"name": "Tomates cherry cortados a la mitad", "unit": "Taza", "amount": "1/2"}, {"name": "Aguacate en cubos", "unit": "Taza", "amount": "1/2"}, {"name": "Tofu marinado y horneado", "unit": "Taza", "amount": "1/2"}, {"name": "Semillas de sésamo tostada", "unit": "Cucharada", "amount": "1"}]}}, {"id": "7b5b0a43-12ae-4f6a-891d-2ea3540498c9", "public_path": "/en/buddha-bowl-recipe", "language": "en", "before": {"seo": {"title": "Buddha Bowl: easy, healthy recipe | Manual de Cocina", "robots": "index,follow", "description": "Buddha Bowl with brown rice, black beans, broccoli, baked tofu, avocado and fresh vegetables. A complete, nutritious meal."}}, "after": {"seo": {"title": "Buddha Bowl: easy, healthy recipe | Manual de Cocina", "robots": "index,follow", "description": "Buddha Bowl with brown rice, black beans, broccoli, baked tofu, avocado and fresh vegetables. A complete, nutritious meal.", "faq": [{"q": "How do I get the tofu to brown?", "a": "Pat it dry and spread the cubes in a single layer on the baking tray. Crowded pieces trap steam and brown less easily."}, {"q": "Can I prepare the components ahead?", "a": "Yes. Refrigerate the rice, beans, tofu and vegetables separately; cut the avocado and assemble the bowl just before serving."}, {"q": "How do I keep the recipe vegan?", "a": "Use tofu and beans as listed and check that the marinade contains no honey, dairy or other animal ingredients."}]}}}, {"id": "fcef53fc-f3a0-4a0a-b593-ae87d1630b6b", "public_path": "/de/buddha-bowl-rezept", "language": "de", "before": {"seo": {"title": "Buddha Bowl: einfaches, gesundes Rezept | Manual de Cocina", "robots": "index,follow", "description": "Buddha Bowl mit braunem Reis, schwarzen Bohnen, Brokkoli, gebackenem Tofu, Avocado und frischem Gemüse. Eine komplette, nahrhafte Mahlzeit."}}, "after": {"seo": {"title": "Buddha Bowl: einfaches, gesundes Rezept | Manual de Cocina", "robots": "index,follow", "description": "Buddha Bowl mit braunem Reis, schwarzen Bohnen, Brokkoli, gebackenem Tofu, Avocado und frischem Gemüse. Eine komplette, nahrhafte Mahlzeit.", "faq": [{"q": "Wie wird der Tofu schön braun?", "a": "Tupfe ihn trocken und verteile die Würfel in einer einzigen Schicht auf dem Blech. Liegen sie zu dicht, staut sich Dampf und sie bräunen schlechter."}, {"q": "Kann ich die Bestandteile vorbereiten?", "a": "Ja. Bewahre Reis, Bohnen, Tofu und Gemüse getrennt im Kühlschrank auf. Schneide die Avocado und stelle die Bowl erst vor dem Servieren zusammen."}, {"q": "Wie bleibt das Rezept vegan?", "a": "Verwende Tofu und Bohnen wie angegeben und prüfe, dass die Marinade keinen Honig, keine Milchprodukte und keine anderen tierischen Zutaten enthält."}]}}}, {"id": "0ba89666-ffd5-41be-b6f5-e22e468054db", "public_path": "/fr/buddha-bowl", "language": "fr", "before": {"seo": {"title": "Buddha Bowl : recette facile et saine | Manual de Cocina", "robots": "index,follow", "description": "Buddha Bowl avec riz complet, haricots noirs, brocoli, tofu cuit, avocat et légumes frais. Un repas complet et nutritif."}}, "after": {"seo": {"title": "Buddha Bowl : recette facile et saine | Manual de Cocina", "robots": "index,follow", "description": "Buddha Bowl avec riz complet, haricots noirs, brocoli, tofu cuit, avocat et légumes frais. Un repas complet et nutritif.", "faq": [{"q": "Comment faire dorer le tofu ?", "a": "Épongez-le et étalez les cubes en une seule couche sur la plaque. S'ils sont trop serrés, la vapeur s'accumule et ils dorent moins bien."}, {"q": "Puis-je préparer les éléments à l'avance ?", "a": "Oui. Conservez séparément le riz, les haricots, le tofu et les légumes au réfrigérateur. Coupez l'avocat et assemblez le bowl au moment de servir."}, {"q": "Comment garder une recette végétalienne ?", "a": "Utilisez le tofu et les haricots indiqués et vérifiez que la marinade ne contient ni miel, ni produit laitier, ni autre ingrédient d'origine animale."}]}}}, {"id": "2fdce208-44c4-4359-b3c8-c0caaa96c315", "public_path": "/it/ricetta-buddha-bowl", "language": "it", "before": {"seo": {"title": "Buddha Bowl: ricetta facile e sana | Manual de Cocina", "robots": "index,follow", "description": "Buddha Bowl con riso integrale, fagioli neri, broccolo, tofu al forno, avocado e verdure fresche. Un pasto completo e nutriente."}}, "after": {"seo": {"title": "Buddha Bowl: ricetta facile e sana | Manual de Cocina", "robots": "index,follow", "description": "Buddha Bowl con riso integrale, fagioli neri, broccolo, tofu al forno, avocado e verdure fresche. Un pasto completo e nutriente.", "faq": [{"q": "Come faccio a dorare il tofu?", "a": "Asciugalo bene e distribuisci i cubetti in un solo strato sulla teglia. Se sono troppo vicini, trattengono vapore e si dorano meno."}, {"q": "Posso preparare i componenti in anticipo?", "a": "Sì. Conserva separatamente riso, fagioli, tofu e verdure in frigorifero; taglia l'avocado e componi la bowl al momento di servire."}, {"q": "Come mantengo vegana la ricetta?", "a": "Usa tofu e fagioli come indicato e controlla che la marinata non contenga miele, latticini o altri ingredienti di origine animale."}]}}}, {"id": "c91e0544-5c47-48de-b7d1-77d1c8fb0fdc", "public_path": "/ja/ブッダボウルのレシピ", "language": "ja", "before": {"seo": {"title": "ブッダボウル：簡単でヘルシーなレシピ | Manual de Cocina", "robots": "index,follow", "description": "玄米、黒豆、ブロッコリー、焼き豆腐、アボカド、新鮮な野菜を合わせたブッダボウル。栄養満点の一皿です。"}}, "after": {"seo": {"title": "ブッダボウル：簡単でヘルシーなレシピ | Manual de Cocina", "robots": "index,follow", "description": "玄米、黒豆、ブロッコリー、焼き豆腐、アボカド、新鮮な野菜を合わせたブッダボウル。栄養満点の一皿です。", "faq": [{"q": "豆腐に焼き色をつけるには？", "a": "表面の水気をよく拭き、天板に重ならないように並べます。詰めすぎると蒸気がこもり、焼き色がつきにくくなります。"}, {"q": "具材を先に準備できますか？", "a": "はい。ご飯、豆、豆腐、野菜は別々の容器で冷蔵します。アボカドを切ってボウルに盛り付けるのは食べる直前にします。"}, {"q": "ヴィーガンにするには？", "a": "材料表どおりに豆腐と豆を使い、漬けだれに蜂蜜、乳製品など動物由来の材料が含まれていないか確認してください。"}]}}}, {"id": "40c7717b-278c-4fd0-ac0b-407486ea8c93", "public_path": "/pt/buddha-bowl", "language": "pt", "before": {"seo": {"title": "Buddha Bowl: receita fácil e saudável | Manual de Cocina", "robots": "index,follow", "description": "Buddha Bowl com arroz integral, feijão preto, brócolis, tofu assado, abacate e vegetais frescos. Uma refeição completa e nutritiva."}}, "after": {"seo": {"title": "Buddha Bowl: receita fácil e saudável | Manual de Cocina", "robots": "index,follow", "description": "Buddha Bowl com arroz integral, feijão preto, brócolis, tofu assado, abacate e vegetais frescos. Uma refeição completa e nutritiva.", "faq": [{"q": "Como faço o tofu dourar?", "a": "Seque bem e espalhe os cubos em uma única camada na assadeira. Quando ficam amontoados, retêm vapor e douram menos."}, {"q": "Posso preparar os componentes antes?", "a": "Sim. Guarde arroz, feijão, tofu e legumes separadamente na geladeira; corte o abacate e monte o bowl na hora de servir."}, {"q": "Como mantenho a receita vegana?", "a": "Use tofu e feijão como indicado e confira se a marinada não leva mel, laticínios ou outros ingredientes de origem animal."}]}}}, {"id": "0da5bae7-4eb5-446c-a2e8-35ec2210cd50", "public_path": "/bowl-de-quinoa-y-garbanzos-con-tahini-y-verdura", "language": "es", "before": {"seo": {"faq": [{"a": "Sí. Cocina la quinoa, asa las verduras y prepara los garbanzos con hasta 3 días de anticipación, guardando cada uno por separado en el refrigerador. Arma el bowl y agrega la salsa de tahini solo al momento de servir para que las verduras conserven su textura.", "q": "¿Puedo preparar este bowl de quinoa y garbanzos con antelación?"}, {"a": "La crema de maní suave o el yogur griego con un poco de aceite de oliva y limón son buenos sustitutos: no tienen el mismo sabor a sésamo, pero aportan la misma cremosidad a la salsa.", "q": "¿Qué puedo usar en lugar de tahini si no lo tengo?"}, {"a": "Sí, todos los ingredientes son de origen vegetal: quinoa, garbanzos, verduras asadas, aguacate y salsa de tahini. Es una opción completa en proteína vegetal y fibra.", "q": "¿Es un bowl apto para vegetarianos y veganos?"}, {"a": "Enjuágala bien antes de cocinarla y usa un poco menos de agua de la que indica el paquete (por ejemplo, 1¾ tazas de agua por cada taza de quinoa). Déjala reposar tapada 5 minutos fuera del fuego antes de separar los granos con un tenedor.", "q": "¿Cómo evito que la quinoa quede aguada?"}], "title": "Bowl de Quinoa y Garbanzos con Tahini | Manual de Cocina", "robots": "index,follow", "description": "Bowl saludable de quinoa, garbanzos crujientes, verduras asadas, aguacate y salsa de tahini. Un plato principal completo y nutritivo."}}, "after": {"seo": {"faq": [{"q": "¿Cómo evito que la quinoa quede aguada?", "a": "Enjuágala, sigue la proporción de agua del envase y deja que repose fuera del fuego antes de soltar los granos con un tenedor. No añadas agua si ya está tierna."}, {"q": "¿Por qué la salsa de tahini se espesa al mezclarla?", "a": "Al incorporar el limón puede espesarse al principio. Añade el agua poco a poco y remueve hasta conseguir una salsa que se pueda verter."}, {"q": "¿Cuándo añado la salsa y el aguacate?", "a": "Justo antes de servir. Si preparas el bowl con antelación, conserva la quinoa, las verduras y la salsa por separado en la nevera."}], "title": "Bowl de Quinoa y Garbanzos con Tahini | Manual de Cocina", "robots": "index,follow", "description": "Bowl saludable de quinoa, garbanzos crujientes, verduras asadas, aguacate y salsa de tahini. Un plato principal completo y nutritivo."}}}, {"id": "288d8105-77aa-42e4-86ef-dd5264cd7861", "public_path": "/en/healthy-quinoa-and-chickpea-bowl-recipe-with-tahini-and-roasted-vegetables-2", "language": "en", "before": {"seo": {"title": "Quinoa and Chickpea Bowl with Tahini and Vegetables | Manual de Cocina", "robots": "index,follow", "description": "Healthy bowl with quinoa, crispy chickpeas, roasted vegetables, avocado and tahini sauce. A complete, nutritious main dish."}}, "after": {"seo": {"title": "Quinoa and Chickpea Bowl with Tahini and Vegetables | Manual de Cocina", "robots": "index,follow", "description": "Healthy bowl with quinoa, crispy chickpeas, roasted vegetables, avocado and tahini sauce. A complete, nutritious main dish.", "faq": [{"q": "How do I keep quinoa from becoming watery?", "a": "Rinse it, follow the water ratio on the package and let it rest off the heat before fluffing with a fork. Do not add water once the grains are tender."}, {"q": "Why does tahini dressing thicken when mixed?", "a": "Adding lemon can make it thicken at first. Add the water gradually and stir until the dressing is pourable."}, {"q": "When should I add the dressing and avocado?", "a": "Just before serving. If preparing ahead, refrigerate the quinoa, vegetables and dressing in separate containers."}]}}}, {"id": "5e3881c5-6438-4a82-a371-06b39c017cc3", "public_path": "/de/gesundes-quinoa-kichererbsen-bowl-rezept-mit-tahini-und-gerostetem-gemuse-2", "language": "de", "before": {"seo": {"title": "Quinoa-Kichererbsen-Bowl mit Tahini und Gemüse | Manual de Cocina", "robots": "index,follow", "description": "Gesunde Bowl mit Quinoa, knusprigen Kichererbsen, geröstetem Gemüse, Avocado und Tahini-Sauce. Ein komplettes, nahrhaftes Hauptgericht."}}, "after": {"seo": {"title": "Quinoa-Kichererbsen-Bowl mit Tahini und Gemüse | Manual de Cocina", "robots": "index,follow", "description": "Gesunde Bowl mit Quinoa, knusprigen Kichererbsen, geröstetem Gemüse, Avocado und Tahini-Sauce. Ein komplettes, nahrhaftes Hauptgericht.", "faq": [{"q": "Wie verhindere ich wässrige Quinoa?", "a": "Spüle sie ab, beachte die Wassermenge auf der Packung und lasse sie nach dem Kochen ruhen, bevor du sie mit einer Gabel auflockerst. Gib kein Wasser mehr dazu, wenn die Körner gar sind."}, {"q": "Warum wird die Tahinisauce beim Rühren dick?", "a": "Zitronensaft kann die Sauce zunächst andicken. Gib das Wasser nach und nach dazu und rühre, bis sie sich gut gießen lässt."}, {"q": "Wann kommen Sauce und Avocado dazu?", "a": "Erst vor dem Servieren. Wenn du vorarbeitest, bewahre Quinoa, Gemüse und Sauce getrennt im Kühlschrank auf."}]}}}, {"id": "8e2cf0a1-1d3f-42de-ba31-487e67bae197", "public_path": "/fr/recette-de-bol-sain-de-quinoa-et-pois-chiches-avec-tahini-et-legumes-rotis", "language": "fr", "before": {"seo": {"title": "Bowl de quinoa, pois chiches, tahini et légumes rôtis | Manual de Cocina", "robots": "index,follow", "description": "Bowl sain à base de quinoa, pois chiches croustillants, légumes rôtis, avocat et sauce tahini. Un plat principal complet et nutritif."}}, "after": {"seo": {"title": "Bowl de quinoa, pois chiches, tahini et légumes rôtis | Manual de Cocina", "robots": "index,follow", "description": "Bowl sain à base de quinoa, pois chiches croustillants, légumes rôtis, avocat et sauce tahini. Un plat principal complet et nutritif.", "faq": [{"q": "Comment éviter un quinoa trop humide ?", "a": "Rincez-le, respectez la quantité d'eau du paquet et laissez-le reposer hors du feu avant de l'égrener à la fourchette. N'ajoutez plus d'eau lorsque les grains sont tendres."}, {"q": "Pourquoi la sauce au tahini épaissit-elle ?", "a": "Le jus de citron peut la faire épaissir au début. Ajoutez l'eau progressivement en remuant, jusqu'à obtenir une sauce fluide."}, {"q": "Quand ajouter la sauce et l'avocat ?", "a": "Juste avant de servir. Pour une préparation à l'avance, gardez le quinoa, les légumes et la sauce séparément au réfrigérateur."}]}}}, {"id": "b2e6ab65-fb37-4b73-a430-27142d692aec", "public_path": "/it/ricetta-sana-in-ciotola-di-quinoa-e-ceci-con-tahini-e-verdure-arrostite-2", "language": "it", "before": {"seo": {"title": "Bowl di quinoa e ceci con tahini e verdure arrostite | Manual de Cocina", "robots": "index,follow", "description": "Bowl sana con quinoa, ceci croccanti, verdure arrostite, avocado e salsa tahini. Un piatto principale completo e nutriente."}}, "after": {"seo": {"title": "Bowl di quinoa e ceci con tahini e verdure arrostite | Manual de Cocina", "robots": "index,follow", "description": "Bowl sana con quinoa, ceci croccanti, verdure arrostite, avocado e salsa tahini. Un piatto principale completo e nutriente.", "faq": [{"q": "Come evito che la quinoa resti acquosa?", "a": "Sciacquala, segui la proporzione d'acqua sulla confezione e falla riposare fuori dal fuoco prima di sgranarla con una forchetta. Non aggiungere acqua quando i chicchi sono già teneri."}, {"q": "Perché la salsa al tahini si addensa?", "a": "Il succo di limone può farla addensare inizialmente. Versa l'acqua poco alla volta e mescola fino a ottenere una salsa fluida."}, {"q": "Quando aggiungo salsa e avocado?", "a": "Appena prima di servire. Se prepari in anticipo, conserva quinoa, verdure e salsa separatamente in frigorifero."}]}}}, {"id": "623927d5-bb1b-425b-94c1-41debe3a10ef", "public_path": "/ja/タヒニとロースト野菜を添えたヘルシーなキヌア", "language": "ja", "before": {"seo": {"title": "キヌアとひよこ豆のタヒニボウル(ロースト野菜添え) | Manual de Cocina", "robots": "index,follow", "description": "キヌア、カリッとしたひよこ豆、ローストした野菜、アボカド、タヒニソースを合わせたヘルシーなボウル。栄養満点の主菜です。"}}, "after": {"seo": {"title": "キヌアとひよこ豆のタヒニボウル(ロースト野菜添え) | Manual de Cocina", "robots": "index,follow", "description": "キヌア、カリッとしたひよこ豆、ローストした野菜、アボカド、タヒニソースを合わせたヘルシーなボウル。栄養満点の主菜です。", "faq": [{"q": "キヌアが水っぽくならないようにするには？", "a": "洗ってから袋に記載された水加減で炊き、火を止めて蒸らしてからフォークでほぐします。粒が柔らかくなった後は水を足しません。"}, {"q": "タヒニソースが混ぜると固くなるのはなぜ？", "a": "レモン汁を加えると一時的に固くなることがあります。水を少しずつ加え、かけやすい濃度になるまで混ぜます。"}, {"q": "ソースとアボカドはいつ加えますか？", "a": "食べる直前です。先に準備する場合は、キヌア、野菜、ソースを別々の容器に入れて冷蔵してください。"}]}}}, {"id": "0d2b71d2-9387-4eb8-b77b-3136ea62bb95", "public_path": "/pt/bowl-de-quinoa-e-grao-de-bico-com-tahine-e-vegetais-assados", "language": "pt", "before": {"seo": {"title": "Bowl de quinoa, grão-de-bico, tahine e vegetais | Manual de Cocina", "robots": "index,follow", "description": "Bowl saudável com quinoa, grão-de-bico crocante, vegetais assados, abacate e molho de tahine. Um prato principal completo e nutritivo."}}, "after": {"seo": {"title": "Bowl de quinoa, grão-de-bico, tahine e vegetais | Manual de Cocina", "robots": "index,follow", "description": "Bowl saudável com quinoa, grão-de-bico crocante, vegetais assados, abacate e molho de tahine. Um prato principal completo e nutritivo.", "faq": [{"q": "Como evito que a quinoa fique aguada?", "a": "Lave, siga a proporção de água da embalagem e deixe descansar fora do fogo antes de soltar os grãos com um garfo. Não acrescente água quando já estiverem macios."}, {"q": "Por que o molho de tahine engrossa ao misturar?", "a": "O limão pode engrossar o molho no início. Acrescente a água aos poucos e mexa até obter uma consistência que possa ser despejada."}, {"q": "Quando acrescento o molho e o abacate?", "a": "Pouco antes de servir. Se adiantar o preparo, guarde quinoa, legumes e molho separadamente na geladeira."}]}}}, {"id": "ad715218-7ce9-4f29-905e-4fcecdc4d954", "public_path": "/batido-grimace-mcdonalds", "language": "es", "before": {"seo": {"faq": [{"a": "Suele ser por usar demasiado hielo o leche vegetal. Empieza con menos líquido del indicado y añade más solo si la licuadora lo necesita para moverse.", "q": "¿Por qué mi batido queda muy líquido?"}, {"a": "Sí, pero perderá cremosidad y parte del dulzor natural. Puedes sustituirlo por medio aguacate para mantener una textura espesa con un sabor más neutro.", "q": "¿Puedo hacerlo sin plátano?"}, {"a": "No es lo ideal: la fruta congelada libera agua con el tiempo y el batido se separa. Es mejor dejar los ingredientes listos en el vaso de la licuadora y procesarlo justo antes de servir.", "q": "¿Se puede preparar la noche anterior?"}, {"a": "Usa menos líquido (empieza con 3/4 de la cantidad indicada) y añade un puñado extra de fruta congelada; licúa por pulsos para que no se caliente demasiado.", "q": "¿Cómo lo hago más espeso, tipo helado?"}], "title": "Batido morado estilo McDonald's (Grimace), casero en 5 minutos", "robots": "index,follow", "description": "Prepara un batido morado inspirado en Grimace con fresas, moras, frambuesas, plátano y leche de almendras. Cremoso y listo en menos de 5 minutos."}}, "after": {"seo": {"faq": [{"q": "¿Cómo consigo un batido más espeso?", "a": "Usa la fruta congelada y empieza con menos leche vegetal. Añade más líquido solo si la licuadora lo necesita para mover la mezcla."}, {"q": "¿Puedo prepararlo sin plátano?", "a": "Sí, pero cambia el dulzor y la textura. Puedes añadir más frutos rojos congelados y ajustar la leche poco a poco para que no quede líquido."}, {"q": "¿Cómo hago la versión vegana?", "a": "Usa leche vegetal y omite la miel o elige el jarabe de arce opcional. Sírvelo recién licuado para conservar la textura."}], "title": "Batido morado estilo McDonald's (Grimace), casero en 5 minutos", "robots": "index,follow", "description": "Prepara un batido morado inspirado en Grimace con fresas, moras, frambuesas, plátano y leche de almendras. Cremoso y listo en menos de 5 minutos."}}}, {"id": "5c1d8428-c204-4ae9-a49f-031928213fe6", "public_path": "/en/milkshake-grimace-mcdonalds-2", "language": "en", "before": {"seo": {"title": "Mixed Berry Smoothie inspired by Grimace: easy recipe | Manual de Cocina", "robots": "index,follow", "description": "Creamy purple smoothie with strawberries, blackberries, raspberries and banana blended with plant-based milk and vanilla. Ready in minutes."}}, "after": {"seo": {"title": "Mixed Berry Smoothie inspired by Grimace: easy recipe | Manual de Cocina", "robots": "index,follow", "description": "Creamy purple smoothie with strawberries, blackberries, raspberries and banana blended with plant-based milk and vanilla. Ready in minutes.", "faq": [{"q": "How do I make a thicker shake?", "a": "Use frozen fruit and start with less plant milk. Add more liquid only if the blender needs it to move the mixture."}, {"q": "Can I make it without banana?", "a": "Yes, although the sweetness and texture will change. Add more frozen berries and adjust the milk gradually so it does not become runny."}, {"q": "How do I make it vegan?", "a": "Use plant milk and leave out the honey or choose the optional maple syrup. Serve immediately after blending for the best texture."}]}}}, {"id": "6e9b80c9-c2a8-4959-9ae2-c5378ee8f1a6", "public_path": "/de/milchshake-grimaze-mcdonalds", "language": "de", "before": {"seo": {"title": "Beeren-Smoothie inspiriert von Grimace: einfaches Rezept | Manual de Cocina", "robots": "index,follow", "description": "Cremiger violetter Smoothie aus Erdbeeren, Brombeeren, Himbeeren und Banane mit Pflanzenmilch und Vanille. In wenigen Minuten fertig."}}, "after": {"seo": {"title": "Beeren-Smoothie inspiriert von Grimace: einfaches Rezept | Manual de Cocina", "robots": "index,follow", "description": "Cremiger violetter Smoothie aus Erdbeeren, Brombeeren, Himbeeren und Banane mit Pflanzenmilch und Vanille. In wenigen Minuten fertig.", "faq": [{"q": "Wie wird der Shake dickflüssiger?", "a": "Verwende gefrorenes Obst und zunächst weniger Pflanzendrink. Gib nur dann mehr Flüssigkeit dazu, wenn der Mixer sie zum Verarbeiten braucht."}, {"q": "Kann ich die Banane weglassen?", "a": "Ja, dadurch ändern sich Süße und Konsistenz. Gib mehr gefrorene Beeren dazu und passe die Flüssigkeit vorsichtig an, damit der Shake nicht zu dünn wird."}, {"q": "Wie wird der Shake vegan?", "a": "Verwende Pflanzendrink und lasse den Honig weg oder nimm den optionalen Ahornsirup. Für die beste Konsistenz direkt nach dem Mixen servieren."}]}}}, {"id": "2df87c4e-3924-4780-a75b-d96e9b26d7c6", "public_path": "/fr/milkshake-grimace-mcdonalds", "language": "fr", "before": {"seo": {"title": "Smoothie aux fruits rouges inspiré de Grimace | Manual de Cocina", "robots": "index,follow", "description": "Smoothie violet crémeux aux fraises, mûres, framboises et banane, avec lait végétal et vanille. Prêt en quelques minutes."}}, "after": {"seo": {"title": "Smoothie aux fruits rouges inspiré de Grimace | Manual de Cocina", "robots": "index,follow", "description": "Smoothie violet crémeux aux fraises, mûres, framboises et banane, avec lait végétal et vanille. Prêt en quelques minutes.", "faq": [{"q": "Comment obtenir un milk-shake plus épais ?", "a": "Utilisez des fruits surgelés et commencez avec moins de boisson végétale. Ajoutez du liquide seulement si le mixeur en a besoin."}, {"q": "Puis-je le préparer sans banane ?", "a": "Oui, mais la douceur et la texture changeront. Ajoutez davantage de fruits rouges surgelés et ajustez le liquide progressivement pour éviter un résultat trop fluide."}, {"q": "Comment le rendre végétalien ?", "a": "Utilisez une boisson végétale et omettez le miel ou choisissez le sirop d'érable facultatif. Servez aussitôt après le mixage pour garder la texture."}]}}}, {"id": "2a15bb28-c3b1-4cf0-a2f0-812f709658e3", "public_path": "/it/frullato-frutti-di-bosco-ispirato-a-grimace", "language": "it", "before": {"seo": {"title": "Frullato ai frutti di bosco ispirato a Grimace | Manual de Cocina", "robots": "index,follow", "description": "Frullato viola cremoso di fragole, more, lamponi e banana con latte vegetale e vaniglia. Pronto in pochi minuti."}}, "after": {"seo": {"title": "Frullato ai frutti di bosco ispirato a Grimace | Manual de Cocina", "robots": "index,follow", "description": "Frullato viola cremoso di fragole, more, lamponi e banana con latte vegetale e vaniglia. Pronto in pochi minuti.", "faq": [{"q": "Come ottengo un frullato più denso?", "a": "Usa frutta congelata e comincia con meno bevanda vegetale. Aggiungi altro liquido solo se serve al frullatore per lavorare il composto."}, {"q": "Posso prepararlo senza banana?", "a": "Sì, ma dolcezza e consistenza cambiano. Puoi aggiungere altri frutti di bosco congelati e regolare il liquido gradualmente, senza renderlo troppo fluido."}, {"q": "Come lo rendo vegano?", "a": "Usa una bevanda vegetale e ometti il miele oppure scegli lo sciroppo d'acero facoltativo. Servilo appena frullato per mantenere la consistenza."}]}}}, {"id": "401379ba-72cf-41a2-a4d6-e956ab26efa0", "public_path": "/ja/ミルクセーキ-しかめっ面-マクドナルド", "language": "ja", "before": {"seo": {"title": "グリメイス風ベリースムージー：簡単レシピ | Manual de Cocina", "robots": "index,follow", "description": "いちご、ブラックベリー、ラズベリー、バナナを植物性ミルクとバニラで仕上げた紫色のクリーミースムージー。数分で完成。"}}, "after": {"seo": {"title": "グリメイス風ベリースムージー：簡単レシピ | Manual de Cocina", "robots": "index,follow", "description": "いちご、ブラックベリー、ラズベリー、バナナを植物性ミルクとバニラで仕上げた紫色のクリーミースムージー。数分で完成。", "faq": [{"q": "濃厚なシェイクにするには？", "a": "冷凍の果物を使い、植物性ミルクは少なめから加えます。ミキサーが回らないときだけ、少しずつ液体を足してください。"}, {"q": "バナナなしでも作れますか？", "a": "はい。ただし甘さと食感は変わります。冷凍ベリーを増やし、植物性ミルクを少しずつ調整すると薄まりにくくなります。"}, {"q": "ヴィーガンにするには？", "a": "植物性ミルクを使い、蜂蜜を省くか、任意のメープルシロップを選びます。食感を保つため、攪拌したらすぐに飲んでください。"}]}}}, {"id": "1335d91c-469d-41ff-beba-2a3be41b2ead", "public_path": "/pt/batida-de-frutas-vermelhas-inspirada-no-grimace", "language": "pt", "before": {"seo": {"title": "Batida de frutas vermelhas inspirada no Grimace | Manual de Cocina", "robots": "index,follow", "description": "Batida roxa cremosa de morangos, amoras, framboesas e banana com leite vegetal e baunilha. Pronta em minutos."}}, "after": {"seo": {"title": "Batida de frutas vermelhas inspirada no Grimace | Manual de Cocina", "robots": "index,follow", "description": "Batida roxa cremosa de morangos, amoras, framboesas e banana com leite vegetal e baunilha. Pronta em minutos.", "faq": [{"q": "Como deixo o shake mais espesso?", "a": "Use frutas congeladas e comece com menos leite vegetal. Acrescente líquido apenas se o liquidificador precisar para bater a mistura."}, {"q": "Posso preparar sem banana?", "a": "Sim, mas a doçura e a textura mudam. Acrescente mais frutas vermelhas congeladas e ajuste o leite aos poucos para não deixar o shake ralo."}, {"q": "Como faço a versão vegana?", "a": "Use leite vegetal e omita o mel ou escolha o xarope de bordo opcional. Sirva logo após bater para manter a textura."}]}}}, {"id": "57a9b600-9e13-49c8-b99a-103a91a4ec37", "public_path": "/receta-saludable-batido-de-frutas-y-vegetales", "language": "es", "before": {"seo": {"faq": [{"a": "Sí, la combinación de fruta, yogur griego y semillas de chía aporta carbohidratos, proteína y fibra suficientes para funcionar como un desayuno ligero pero nutritivo.", "q": "¿Puedo tomar este batido como desayuno completo?"}, {"a": "Apenas se percibe: el dulzor del plátano y la manzana cubre el sabor de la espinaca, que principalmente aporta color y nutrientes sin dominar el sabor final.", "q": "¿Se nota el sabor de la espinaca en el batido?"}, {"a": "Sí, sustituye el yogur griego por yogur de coco o de almendra; ya usa leche vegetal como base, así que el batido queda igual de cremoso.", "q": "¿Puedo preparar este batido sin lácteos?"}, {"a": "Se recomienda tomarlo recién hecho. Si necesitas guardarlo, hazlo en el refrigerador en un recipiente hermético hasta por 24 horas y agítalo bien antes de servir.", "q": "¿Cuánto tiempo se conserva el batido ya preparado?"}], "title": "Batido Energizante de Frutas | Manual de Cocina", "robots": "index,follow", "description": "Batido de plátano, manzana, espinacas, fresas y pepino con yogur griego y leche de almendras. Listo en minutos, ideal para el desayuno."}}, "after": {"seo": {"faq": [{"q": "¿Este batido sustituye un desayuno completo?", "a": "Puede formar parte del desayuno, pero una ración no cubre necesariamente las necesidades de cada persona. Su composición depende de las cantidades, el yogur y la bebida vegetal elegidos."}, {"q": "¿Puedo prepararlo sin lácteos?", "a": "Sí. Sustituye el yogur griego por uno vegetal sin azúcar y comprueba la etiqueta de la bebida vegetal. El sabor, la textura y la proteína pueden variar."}, {"q": "¿Cómo evito los trozos de espinaca?", "a": "Tritura primero la leche vegetal con el yogur y las espinacas. Después incorpora la fruta y procesa hasta conseguir una mezcla uniforme."}], "title": "Batido Energizante de Frutas | Manual de Cocina", "robots": "index,follow", "description": "Batido de plátano, manzana, espinacas, fresas y pepino con yogur griego y leche de almendras. Listo en minutos, ideal para el desayuno."}}}, {"id": "81c84f3b-edec-48bc-9ff4-a73bfca2688c", "public_path": "/en/energizing-fruit-and-vegetable-smoothie", "language": "en", "before": {"seo": {"title": "Energizing Fruit and Vegetable Smoothie: easy recipe | Manual de Cocina", "robots": "index,follow", "description": "Smoothie with banana, apple, spinach, strawberries and cucumber, with Greek yogurt and almond milk. Ready in minutes, great for breakfast."}}, "after": {"seo": {"title": "Energizing Fruit and Vegetable Smoothie: easy recipe | Manual de Cocina", "robots": "index,follow", "description": "Smoothie with banana, apple, spinach, strawberries and cucumber, with Greek yogurt and almond milk. Ready in minutes, great for breakfast.", "faq": [{"q": "Does this smoothie replace a complete breakfast?", "a": "It can be part of breakfast, but one serving does not necessarily meet everyone's needs. Its composition depends on the quantities, yogurt and plant milk used."}, {"q": "Can I make it dairy-free?", "a": "Yes. Replace the Greek yogurt with unsweetened plant-based yogurt and check the plant milk label. Flavor, texture and protein content may change."}, {"q": "How do I avoid pieces of spinach?", "a": "Blend the plant milk, yogurt and spinach first. Then add the fruit and blend until smooth."}]}}}, {"id": "e2581453-10ed-4668-bdfc-0b546e15a7d0", "public_path": "/de/gesundes-obst-und-gemuse-smoothie-rezept-2", "language": "de", "before": {"seo": {"title": "Energiespendender Obst-Gemüse-Smoothie: einfaches Rezept | Manual de Cocina", "robots": "index,follow", "description": "Smoothie aus Banane, Apfel, Spinat, Erdbeeren und Gurke mit griechischem Joghurt und Mandelmilch. In wenigen Minuten fertig, ideal zum Frühstück."}}, "after": {"seo": {"title": "Energiespendender Obst-Gemüse-Smoothie: einfaches Rezept | Manual de Cocina", "robots": "index,follow", "description": "Smoothie aus Banane, Apfel, Spinat, Erdbeeren und Gurke mit griechischem Joghurt und Mandelmilch. In wenigen Minuten fertig, ideal zum Frühstück.", "faq": [{"q": "Ersetzt dieser Smoothie ein vollständiges Frühstück?", "a": "Er kann zum Frühstück gehören, deckt aber nicht zwangsläufig den Bedarf jeder Person. Seine Zusammensetzung hängt von den Mengen, dem Joghurt und dem Pflanzendrink ab."}, {"q": "Kann ich ihn ohne Milchprodukte zubereiten?", "a": "Ja. Ersetze den griechischen Joghurt durch ungesüßten Pflanzenjoghurt und prüfe das Etikett des Pflanzendrinks. Geschmack, Konsistenz und Proteingehalt können sich ändern."}, {"q": "Wie vermeide ich Spinatstücke?", "a": "Mixe zuerst Pflanzendrink, Joghurt und Spinat. Gib anschließend das Obst dazu und mixe alles glatt."}]}}}, {"id": "9e7afc25-5fd5-4adf-8f51-edd8a00ef82d", "public_path": "/fr/recette-de-smoothie-sain-aux-fruits-et-legumes-2", "language": "fr", "before": {"seo": {"title": "Smoothie énergisant aux fruits et légumes | Manual de Cocina", "robots": "index,follow", "description": "Smoothie à la banane, la pomme, les épinards, les fraises et le concombre, avec yaourt grec et lait d'amande. Prêt en quelques minutes."}}, "after": {"seo": {"title": "Smoothie énergisant aux fruits et légumes | Manual de Cocina", "robots": "index,follow", "description": "Smoothie à la banane, la pomme, les épinards, les fraises et le concombre, avec yaourt grec et lait d'amande. Prêt en quelques minutes.", "faq": [{"q": "Ce smoothie remplace-t-il un petit-déjeuner complet ?", "a": "Il peut faire partie du petit-déjeuner, mais une portion ne couvre pas forcément les besoins de chacun. Sa composition dépend des quantités, du yaourt et de la boisson végétale utilisés."}, {"q": "Puis-je le préparer sans produits laitiers ?", "a": "Oui. Remplacez le yaourt grec par un yaourt végétal nature sans sucre et vérifiez l'étiquette de la boisson végétale. Le goût, la texture et les protéines peuvent varier."}, {"q": "Comment éviter les morceaux d'épinards ?", "a": "Mixez d'abord la boisson végétale, le yaourt et les épinards. Ajoutez ensuite les fruits et mixez jusqu'à obtenir une texture lisse."}]}}}, {"id": "3bdb43f9-ed94-4dee-93a7-6cb251893ab4", "public_path": "/it/frullato-energizzante-frutta-verdura", "language": "it", "before": {"seo": {"title": "Frullato energizzante di frutta e verdura | Manual de Cocina", "robots": "index,follow", "description": "Frullato con banana, mela, spinaci, fragole e cetriolo, con yogurt greco e latte di mandorla. Pronto in pochi minuti, ideale per colazione."}}, "after": {"seo": {"title": "Frullato energizzante di frutta e verdura | Manual de Cocina", "robots": "index,follow", "description": "Frullato con banana, mela, spinaci, fragole e cetriolo, con yogurt greco e latte di mandorla. Pronto in pochi minuti, ideale per colazione.", "faq": [{"q": "Questo frullato sostituisce una colazione completa?", "a": "Può far parte della colazione, ma una porzione non copre necessariamente i bisogni di tutti. La composizione dipende dalle dosi, dallo yogurt e dalla bevanda vegetale scelti."}, {"q": "Posso prepararlo senza latticini?", "a": "Sì. Sostituisci lo yogurt greco con yogurt vegetale senza zucchero e controlla l'etichetta della bevanda vegetale. Sapore, consistenza e proteine possono cambiare."}, {"q": "Come evito i pezzetti di spinaci?", "a": "Frulla prima la bevanda vegetale con lo yogurt e gli spinaci. Poi aggiungi la frutta e lavora fino a ottenere un composto uniforme."}]}}}, {"id": "1848f499-9479-4a15-b125-cc49f212a303", "public_path": "/ja/健康的な果物と野菜のスムージー-レシピ", "language": "ja", "before": {"seo": {"title": "元気になるフルーツ野菜スムージー：簡単レシピ | Manual de Cocina", "robots": "index,follow", "description": "バナナ、りんご、ほうれん草、いちご、きゅうりにギリシャヨーグルトとアーモンドミルクを合わせたスムージー。数分で完成、朝食にぴったり。"}}, "after": {"seo": {"title": "元気になるフルーツ野菜スムージー：簡単レシピ | Manual de Cocina", "robots": "index,follow", "description": "バナナ、りんご、ほうれん草、いちご、きゅうりにギリシャヨーグルトとアーモンドミルクを合わせたスムージー。数分で完成、朝食にぴったり。", "faq": [{"q": "このスムージーだけで朝食になりますか？", "a": "朝食の一部にはなりますが、1杯で誰にでも必要な栄養を満たせるとは限りません。量や、選ぶヨーグルトと植物性ミルクによって成分は変わります。"}, {"q": "乳製品なしでも作れますか？", "a": "はい。ギリシャヨーグルトを無糖の植物性ヨーグルトに替え、植物性ミルクの表示も確認します。味、食感、たんぱく質量は変わる場合があります。"}, {"q": "ほうれん草のかけらを残さないコツは？", "a": "先に植物性ミルク、ヨーグルト、ほうれん草を攪拌します。その後で果物を加え、なめらかになるまで混ぜます。"}]}}}, {"id": "fd387fa1-d3d5-4f88-8e8e-9844e6114992", "public_path": "/pt/batida-energizante-de-frutas-e-vegetais", "language": "pt", "before": {"seo": {"title": "Batida Energizante de Frutas e Vegetais: receita fácil | Manual de Cocina", "robots": "index,follow", "description": "Batida de banana, maçã, espinafre, morango e pepino, com iogurte grego e leite de amêndoas. Pronta em minutos, ótima para o café da manhã."}}, "after": {"seo": {"title": "Batida Energizante de Frutas e Vegetais: receita fácil | Manual de Cocina", "robots": "index,follow", "description": "Batida de banana, maçã, espinafre, morango e pepino, com iogurte grego e leite de amêndoas. Pronta em minutos, ótima para o café da manhã.", "faq": [{"q": "Este smoothie substitui um café da manhã completo?", "a": "Pode fazer parte do café da manhã, mas uma porção não atende necessariamente às necessidades de todos. A composição depende das quantidades, do iogurte e da bebida vegetal escolhidos."}, {"q": "Posso preparar sem laticínios?", "a": "Sim. Troque o iogurte grego por iogurte vegetal sem açúcar e confira o rótulo da bebida vegetal. Sabor, textura e teor de proteína podem mudar."}, {"q": "Como evito pedaços de espinafre?", "a": "Bata primeiro a bebida vegetal, o iogurte e o espinafre. Depois junte as frutas e bata até ficar homogêneo."}]}}}, {"id": "1f1ab8d4-0e85-4faa-ac4c-96f581cfbe90", "public_path": "/receta-arepa-con-todo", "language": "es", "before": {"seo": {"faq": [{"a": "Sí, esa es la base de la arepa de trigo venezolana. Sustituye la harina de maíz precocida por harina de trigo panificable en la misma cantidad y sigue el mismo proceso de amasado y cocción.", "q": "¿Puedo usar harina de trigo en lugar de harina de maíz?"}, {"a": "Generalmente es porque se cocinan a fuego muy alto: el exterior se dora antes de que el interior termine de cocinarse. Cocínalas a fuego medio, tapando la sartén los primeros minutos para ayudar a cocinar el centro.", "q": "¿Por qué mis arepas quedan crudas por dentro?"}, {"a": "Frijoles refritos con queso, pollo desmechado, huevo revuelto o solo aguacate y queso son opciones igual de tradicionales y rápidas de preparar.", "q": "¿Qué relleno puedo usar si no tengo carne desmechada?"}, {"a": "Debe sonar hueca al golpearla suavemente y tener un color dorado uniforme por ambos lados; si aún suena densa, cocínala unos minutos más.", "q": "¿Cómo sé que la arepa ya está lista para abrirla?"}], "title": "Arepa con todo: receta tradicional | Manual de Cocina", "robots": "index,follow", "description": "Receta de arepa con todo, rellena de carne desmechada, frijoles, queso, aguacate y hogao. Masa, cocción y armado paso a paso."}, "ingredients": [{"name": "Harina de maíz precocida (harina de maíz blanco o amarillo)", "unit": "tazas de", "group": "Para la arepa", "amount": "2"}, {"name": "harina de trigo panificable (opcional, para la versión venezolana de arepa de trigo)", "unit": "tazas de", "group": "Para la arepa", "amount": "2"}, {"name": "Agua tibia", "unit": "tazas de", "group": "Para la arepa", "amount": "2 1/2"}, {"name": "Sal", "unit": "cucharada de", "group": "Para la arepa", "amount": "1"}, {"name": "Aceite vegetal o mantequilla para cocinar", "unit": "", "group": "Para la arepa", "amount": "al gusto"}, {"name": "Carne desmechada (puedes utilizar carne de res, pollo o cerdo)", "unit": "tazas de", "group": "Para el relleno", "amount": "2"}, {"name": "Frijoles refritos", "unit": "taza de", "group": "Para el relleno", "amount": "1"}, {"name": "Queso rallado (queso blanco o queso tipo mozzarella)", "unit": "taza de", "group": "Para el relleno", "amount": "1"}, {"name": "Aguacate en rodajas", "unit": "unidad de", "group": "Para el relleno", "amount": "1"}, {"name": "Hogao (salsa de tomate y cebolla)", "unit": "taza de", "group": "Para el relleno", "amount": "1/2"}, {"name": "Tocineta o bacon crujiente (opcional)", "unit": "", "group": "Para el relleno", "amount": "al gusto"}, {"name": "Salsa de tu elección (ají, tártara, guasacaca, etc.)", "unit": "", "group": "Para el relleno", "amount": "al gusto"}], "notes": "<h3>Consejos</h3>\n<ul>\n<li>Deja reposar la masa 5 minutos antes de formar los discos: se hidrata mejor y es menos probable que se agriete al aplanarla.</li>\n<li>Cocina las arepas tapadas los primeros minutos para que el interior se cocine bien sin que el exterior se queme; destápalas al final para que la superficie quede crujiente.</li>\n<li>Golpea suavemente los bordes de la arepa mientras se cocina para saber si ya está lista por dentro: debe sonar hueco.</li>\n</ul>\n<h3>Sustituciones</h3>\n<ul>\n<li>Si prefieres la versión venezolana de \"arepa de trigo\", sustituye la harina de maíz por harina de trigo panificable en la misma proporción.</li>\n<li>La carne desmechada admite res, pollo o cerdo, según lo que tengas o prefieras; también funciona con carne mechada sobrante de otra preparación.</li>\n<li>Sin hogao, un sofrito simple de cebolla y tomate con sal y comino cumple una función similar como base del relleno.</li>\n</ul>\n<h3>Conservación</h3>\n<ul>\n<li>Guarda las arepas ya cocidas (sin relleno) en un recipiente hermético en el refrigerador hasta 3 días, o congélalas hasta por un mes.</li>\n<li>Recalienta las arepas en sartén o tostadora antes de rellenarlas, para que recuperen su textura crujiente por fuera.</li>\n<li>Guarda el relleno de carne desmechada por separado y recaliéntalo hasta que esté bien caliente antes de armar la arepa.</li>\n</ul>\n<p class=\"md-sources\">Fuente: <a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-temperature-chart\">USDA FSIS – Safe Minimum Internal Temperature Chart</a></p>"}, "after": {"seo": {"faq": [{"q": "¿Puedo cambiar la harina de maíz por trigo en la misma proporción?", "a": "No. La harina de trigo y la de maíz precocida absorben el agua y forman la masa de manera distinta. Para esta preparación usa maíz precocido; una arepa de trigo necesita su propia fórmula."}, {"q": "¿Por qué la arepa se dora y sigue cruda por dentro?", "a": "El fuego puede estar demasiado alto o el disco ser muy grueso. Cocina a fuego medio, como indica el método, y abre una para comprobar que el centro esté cocido antes de rellenar."}, {"q": "¿Qué relleno puedo usar sin carne?", "a": "Frijoles refritos, aguacate y queso son opciones sencillas. Para una versión vegana omite el queso, la mantequilla, la tocineta y las salsas con ingredientes animales."}], "title": "Arepa con todo: receta tradicional | Manual de Cocina", "robots": "index,follow", "description": "Receta de arepa con todo, rellena de carne desmechada, frijoles, queso, aguacate y hogao. Masa, cocción y armado paso a paso."}, "ingredients": [{"name": "Harina de maíz precocida (harina de maíz blanco o amarillo)", "unit": "tazas de", "group": "Para la arepa", "amount": "2"}, {"name": "Agua tibia", "unit": "tazas de", "group": "Para la arepa", "amount": "2 1/2"}, {"name": "Sal", "unit": "cucharada de", "group": "Para la arepa", "amount": "1"}, {"name": "Aceite vegetal o mantequilla para cocinar", "unit": "", "group": "Para la arepa", "amount": "al gusto"}, {"name": "Carne desmechada (puedes utilizar carne de res, pollo o cerdo)", "unit": "tazas de", "group": "Para el relleno", "amount": "2"}, {"name": "Frijoles refritos", "unit": "taza de", "group": "Para el relleno", "amount": "1"}, {"name": "Queso rallado (queso blanco o queso tipo mozzarella)", "unit": "taza de", "group": "Para el relleno", "amount": "1"}, {"name": "Aguacate en rodajas", "unit": "unidad de", "group": "Para el relleno", "amount": "1"}, {"name": "Hogao (salsa de tomate y cebolla)", "unit": "taza de", "group": "Para el relleno", "amount": "1/2"}, {"name": "Tocineta o bacon crujiente (opcional)", "unit": "", "group": "Para el relleno", "amount": "al gusto"}, {"name": "Salsa de tu elección (ají, tártara, guasacaca, etc.)", "unit": "", "group": "Para el relleno", "amount": "al gusto"}], "notes": "Esta preparación usa harina de maíz precocida. No se sustituye por trigo en proporción 1:1: las arepas de trigo necesitan una fórmula propia. Ajusta el agua poco a poco hasta obtener una masa manejable y deja reposar 5 minutos. Conserva las arepas cocidas y el relleno por separado en la nevera; recalienta el relleno antes de montar."}}, {"id": "964fa3fa-05f2-4fe5-a78a-70804c9f0117", "public_path": "/en/recipe-arepa-with-everything", "language": "en", "before": {"seo": {"title": "Arepa con Todo: Traditional Recipe | Manual de Cocina", "robots": "index,follow", "description": "Loaded arepa recipe filled with shredded meat, beans, cheese, avocado and hogao. Dough, cooking and step-by-step assembly."}, "ingredients": [{"name": "For the arepa", "unit": "", "amount": ""}, {"name": "Precooked corn flour (white or yellow corn flour)", "unit": "cups", "amount": "2"}, {"name": "Pan bread flour, if you want to make a Venezuelan-style arepa.", "unit": "", "amount": ""}, {"name": "Warm water", "unit": "cups", "amount": "2 1/2"}, {"name": "Salt", "unit": "tablespoon", "amount": "1"}, {"name": "Vegetable oil or butter, for cooking", "unit": "", "amount": ""}, {"name": "For the filling", "unit": "", "amount": ""}, {"name": "Shredded meat (you can use beef, chicken or pork)", "unit": "", "amount": ""}, {"name": "Refried beans", "unit": "", "amount": ""}, {"name": "Shredded cheese (queso blanco or mozzarella-style cheese)", "unit": "", "amount": ""}, {"name": "Avocado, sliced", "unit": "", "amount": ""}, {"name": "Hogao (tomato and onion sauce)", "unit": "", "amount": ""}, {"name": "Crispy bacon (optional)", "unit": "", "amount": ""}, {"name": "Sauce of your choice (ají, tartar, guasacaca, etc.)", "unit": "", "amount": ""}], "notes": "This recipe works for both the Colombian and Venezuelan versions of the arepa: use precooked corn flour for either, or pan bread flour if you prefer the Venezuelan wheat-flour variant. The filling can be adapted to whatever you have on hand."}, "after": {"seo": {"title": "Arepa con Todo: Traditional Recipe | Manual de Cocina", "robots": "index,follow", "description": "Loaded arepa recipe filled with shredded meat, beans, cheese, avocado and hogao. Dough, cooking and step-by-step assembly.", "faq": [{"q": "Can I replace precooked corn flour with wheat flour one for one?", "a": "No. Wheat flour and precooked corn flour absorb water and form dough differently. Use precooked corn flour here; wheat arepas need their own recipe."}, {"q": "Why is my arepa brown outside but raw inside?", "a": "The heat may be too high or the disc too thick. Cook over medium heat as directed and cut one open to check the center before filling."}, {"q": "What can I use for a meat-free filling?", "a": "Refried beans, avocado and cheese are simple options. For a vegan version, leave out cheese, butter, bacon and sauces containing animal ingredients."}]}, "ingredients": [{"name": "Precooked corn flour (white or yellow corn flour)", "unit": "cups", "amount": "2", "group": "For the arepa"}, {"name": "Warm water", "unit": "cups", "amount": "2 1/2", "group": "For the arepa"}, {"name": "Salt", "unit": "tablespoon", "amount": "1", "group": "For the arepa"}, {"name": "Vegetable oil or butter, for cooking", "unit": "", "amount": "", "group": "For the arepa"}, {"name": "Shredded meat (you can use beef, chicken or pork)", "unit": "cups", "amount": "2", "group": "For the filling"}, {"name": "Refried beans", "unit": "cup", "amount": "1", "group": "For the filling"}, {"name": "Shredded cheese (queso blanco or mozzarella-style cheese)", "unit": "cup", "amount": "1", "group": "For the filling"}, {"name": "Avocado, sliced", "unit": "", "amount": "1", "group": "For the filling"}, {"name": "Hogao (tomato and onion sauce)", "unit": "cup", "amount": "1/2", "group": "For the filling"}, {"name": "Crispy bacon (optional)", "unit": "", "amount": "", "group": "For the filling"}, {"name": "Sauce of your choice (ají, tartar, guasacaca, etc.)", "unit": "", "amount": "", "group": "For the filling"}], "notes": "This recipe uses precooked corn flour. Do not replace it one for one with wheat flour: wheat arepas need a separate formula. Add water gradually until the dough is workable and let it rest for 5 minutes. Refrigerate cooked arepas and filling separately; reheat the filling before assembling."}}, {"id": "4ae97065-6deb-47f2-9f74-1a8247dca81c", "public_path": "/de/rezept-arepa-mit-allem", "language": "de", "before": {"seo": {"title": "Arepa con Todo: Traditionelles Rezept | Manual de Cocina", "robots": "index,follow", "description": "Rezept für gefüllte Arepa mit zerpflücktem Fleisch, Bohnen, Käse, Avocado und Hogao. Teig, Zubereitung und Schritt-für-Schritt-Füllung."}, "ingredients": [{"name": "Für die Arepa", "unit": "", "amount": ""}, {"name": "Vorgekochtes Maismehl (weißes oder gelbes Maismehl)", "unit": "Tassen", "amount": "2"}, {"name": "Weizenmehl, falls du eine venezolanische Arepa machen möchtest.", "unit": "", "amount": ""}, {"name": "Lauwarmes Wasser", "unit": "Tassen", "amount": "2 1/2"}, {"name": "Salz", "unit": "Esslöffel", "amount": "1"}, {"name": "Pflanzenöl oder Butter zum Braten", "unit": "", "amount": ""}, {"name": "Für die Füllung", "unit": "", "amount": ""}, {"name": "Zerpflücktes Fleisch (Rind, Hähnchen oder Schwein)", "unit": "", "amount": ""}, {"name": "Gebratene Bohnen (Frijoles refritos)", "unit": "", "amount": ""}, {"name": "Geriebener Käse (Queso blanco oder Mozzarella-Käse)", "unit": "", "amount": ""}, {"name": "Avocado, in Scheiben", "unit": "", "amount": ""}, {"name": "Hogao (Tomaten-Zwiebel-Sauce)", "unit": "", "amount": ""}, {"name": "Knuspriger Speck (optional)", "unit": "", "amount": ""}, {"name": "Sauce nach Wahl (Ají, Tatarensauce, Guasacaca usw.)", "unit": "", "amount": ""}], "notes": "Dieses Rezept eignet sich sowohl für die kolumbianische als auch für die venezolanische Version der Arepa: Verwende vorgekochtes Maismehl für beide, oder Weizenmehl, wenn du die venezolanische Variante bevorzugst. Die Füllung kann an das angepasst werden, was du zur Hand hast."}, "after": {"seo": {"title": "Arepa con Todo: Traditionelles Rezept | Manual de Cocina", "robots": "index,follow", "description": "Rezept für gefüllte Arepa mit zerpflücktem Fleisch, Bohnen, Käse, Avocado und Hogao. Teig, Zubereitung und Schritt-für-Schritt-Füllung.", "faq": [{"q": "Kann ich vorgekochtes Maismehl eins zu eins durch Weizenmehl ersetzen?", "a": "Nein. Weizenmehl und vorgekochtes Maismehl nehmen Wasser unterschiedlich auf und bilden andere Teige. Verwende hier vorgekochtes Maismehl; Weizenarepas brauchen ein eigenes Rezept."}, {"q": "Warum ist die Arepa außen braun und innen noch roh?", "a": "Die Hitze kann zu hoch oder der Fladen zu dick sein. Gare sie wie beschrieben bei mittlerer Hitze und schneide eine zur Kontrolle auf, bevor du sie füllst."}, {"q": "Welche Füllung geht ohne Fleisch?", "a": "Bohnenmus, Avocado und Käse sind einfache Möglichkeiten. Für eine vegane Variante lasse Käse, Butter, Bacon und Saucen mit tierischen Zutaten weg."}]}, "ingredients": [{"name": "Vorgekochtes Maismehl (weißes oder gelbes Maismehl)", "unit": "Tassen", "amount": "2", "group": "Für die Arepa"}, {"name": "Lauwarmes Wasser", "unit": "Tassen", "amount": "2 1/2", "group": "Für die Arepa"}, {"name": "Salz", "unit": "Esslöffel", "amount": "1", "group": "Für die Arepa"}, {"name": "Pflanzenöl oder Butter zum Braten", "unit": "", "amount": "", "group": "Für die Arepa"}, {"name": "Zerpflücktes Fleisch (Rind, Hähnchen oder Schwein)", "unit": "Tassen", "amount": "2", "group": "Für die Füllung"}, {"name": "Gebratene Bohnen (Frijoles refritos)", "unit": "Tasse", "amount": "1", "group": "Für die Füllung"}, {"name": "Geriebener Käse (Queso blanco oder Mozzarella-Käse)", "unit": "Tasse", "amount": "1", "group": "Für die Füllung"}, {"name": "Avocado, in Scheiben", "unit": "", "amount": "1", "group": "Für die Füllung"}, {"name": "Hogao (Tomaten-Zwiebel-Sauce)", "unit": "Tasse", "amount": "1/2", "group": "Für die Füllung"}, {"name": "Knuspriger Speck (optional)", "unit": "", "amount": "", "group": "Für die Füllung"}, {"name": "Sauce nach Wahl (Ají, Tatarensauce, Guasacaca usw.)", "unit": "", "amount": "", "group": "Für die Füllung"}], "notes": "Dieses Rezept verwendet vorgekochtes Maismehl. Ersetze es nicht eins zu eins durch Weizenmehl: Weizenarepas benötigen eine eigene Rezeptur. Gib Wasser nach und nach zu einem formbaren Teig und lasse ihn 5 Minuten ruhen. Bewahre gegarte Arepas und Füllung getrennt im Kühlschrank auf; erhitze die Füllung vor dem Zusammensetzen."}}, {"id": "ac3e89c9-a5be-4495-8cc5-73bb8a1fcc5b", "public_path": "/fr/recette-arepa-avec-tout", "language": "fr", "before": {"seo": {"title": "Arepa con Todo : recette traditionnelle | Manual de Cocina", "robots": "index,follow", "description": "Recette d'arepa garnie de viande effilochée, haricots, fromage, avocat et hogao. Pâte, cuisson et garniture étape par étape."}, "ingredients": [{"name": "Pour l'arepa", "unit": "", "amount": ""}, {"name": "Farine de maïs précuite (farine de maïs blanc ou jaune)", "unit": "tasses de", "amount": "2"}, {"name": "Farine de blé (pan) si vous souhaitez préparer une arepa vénézuélienne.", "unit": "", "amount": ""}, {"name": "Eau tiède", "unit": "tasses de", "amount": "2 1/2"}, {"name": "Sel", "unit": "cuillère à soupe de", "amount": "1"}, {"name": "Huile végétale ou beurre pour la cuisson", "unit": "", "amount": ""}, {"name": "Pour la garniture", "unit": "", "amount": ""}, {"name": "Viande effilochée (bœuf, poulet ou porc)", "unit": "", "amount": ""}, {"name": "Haricots frits (frijoles refritos)", "unit": "", "amount": ""}, {"name": "Fromage râpé (queso blanco ou fromage type mozzarella)", "unit": "", "amount": ""}, {"name": "Avocat en tranches", "unit": "", "amount": ""}, {"name": "Hogao (sauce tomate et oignon)", "unit": "", "amount": ""}, {"name": "Bacon croustillant (facultatif)", "unit": "", "amount": ""}, {"name": "Sauce de votre choix (ají, sauce tartare, guasacaca, etc.)", "unit": "", "amount": ""}], "notes": "Cette recette convient aussi bien à la version colombienne qu'à la version vénézuélienne de l'arepa : utilisez de la farine de maïs précuite pour les deux, ou de la farine de blé si vous préférez la variante vénézuélienne. La garniture peut être adaptée à ce que vous avez sous la main."}, "after": {"seo": {"title": "Arepa con Todo : recette traditionnelle | Manual de Cocina", "robots": "index,follow", "description": "Recette d'arepa garnie de viande effilochée, haricots, fromage, avocat et hogao. Pâte, cuisson et garniture étape par étape.", "faq": [{"q": "Peut-on remplacer la farine de maïs précuite par la même quantité de blé ?", "a": "Non. Ces farines absorbent l'eau et forment la pâte différemment. Utilisez ici de la farine de maïs précuite ; les arepas de blé demandent une recette adaptée."}, {"q": "Pourquoi l'arepa dore-t-elle sans cuire au centre ?", "a": "Le feu peut être trop fort ou le disque trop épais. Cuisez à feu moyen comme indiqué et ouvrez-en une pour vérifier le centre avant de la garnir."}, {"q": "Quelle garniture choisir sans viande ?", "a": "La purée de haricots, l'avocat et le fromage sont des options simples. Pour une version végétalienne, omettez fromage, beurre, bacon et sauces contenant des ingrédients animaux."}]}, "ingredients": [{"name": "Farine de maïs précuite (farine de maïs blanc ou jaune)", "unit": "tasses de", "amount": "2", "group": "Pour l'arepa"}, {"name": "Eau tiède", "unit": "tasses de", "amount": "2 1/2", "group": "Pour l'arepa"}, {"name": "Sel", "unit": "cuillère à soupe de", "amount": "1", "group": "Pour l'arepa"}, {"name": "Huile végétale ou beurre pour la cuisson", "unit": "", "amount": "", "group": "Pour l'arepa"}, {"name": "Viande effilochée (bœuf, poulet ou porc)", "unit": "tasses", "amount": "2", "group": "Pour la garniture"}, {"name": "Haricots frits (frijoles refritos)", "unit": "tasse", "amount": "1", "group": "Pour la garniture"}, {"name": "Fromage râpé (queso blanco ou fromage type mozzarella)", "unit": "tasse", "amount": "1", "group": "Pour la garniture"}, {"name": "Avocat en tranches", "unit": "", "amount": "1", "group": "Pour la garniture"}, {"name": "Hogao (sauce tomate et oignon)", "unit": "tasse", "amount": "1/2", "group": "Pour la garniture"}, {"name": "Bacon croustillant (facultatif)", "unit": "", "amount": "", "group": "Pour la garniture"}, {"name": "Sauce de votre choix (ají, sauce tartare, guasacaca, etc.)", "unit": "", "amount": "", "group": "Pour la garniture"}], "notes": "Cette préparation utilise de la farine de maïs précuite. Ne la remplacez pas par la même quantité de blé : les arepas de blé demandent une formule adaptée. Ajoutez l’eau progressivement pour obtenir une pâte malléable et laissez reposer 5 minutes. Réfrigérez séparément les arepas cuites et la garniture ; réchauffez la garniture avant de les assembler."}}, {"id": "da647e2a-a664-4cfb-a2c0-91c942a319bb", "public_path": "/it/ricetta-arepa-con-tutto", "language": "it", "before": {"seo": {"title": "Arepa con Todo: ricetta tradizionale | Manual de Cocina", "robots": "index,follow", "description": "Ricetta dell'arepa farcita con carne sfilacciata, fagioli, formaggio, avocado e hogao. Impasto, cottura e farcitura passo dopo passo."}, "ingredients": [{"name": "Per l'arepa", "unit": "", "amount": ""}, {"name": "Farina di mais precotta (farina di mais bianco o giallo)", "unit": "tazze di", "amount": "2"}, {"name": "Farina di grano (pan) se si desidera preparare un'arepa venezuelana.", "unit": "", "amount": ""}, {"name": "Acqua tiepida", "unit": "tazze di", "amount": "2 1/2"}, {"name": "Sale", "unit": "cucchiaio di", "amount": "1"}, {"name": "Olio vegetale o burro per la cottura", "unit": "", "amount": ""}, {"name": "Per il ripieno", "unit": "", "amount": ""}, {"name": "Carne sfilacciata (manzo, pollo o maiale)", "unit": "", "amount": ""}, {"name": "Fagioli fritti (frijoles refritos)", "unit": "", "amount": ""}, {"name": "Formaggio grattugiato (queso blanco o formaggio tipo mozzarella)", "unit": "", "amount": ""}, {"name": "Avocado a fette", "unit": "", "amount": ""}, {"name": "Hogao (salsa di pomodoro e cipolla)", "unit": "", "amount": ""}, {"name": "Pancetta croccante (facoltativa)", "unit": "", "amount": ""}, {"name": "Salsa a scelta (ají, salsa tartara, guasacaca, ecc.)", "unit": "", "amount": ""}], "notes": "Questa ricetta è adatta sia alla versione colombiana che a quella venezuelana dell'arepa: usa farina di mais precotta per entrambe, oppure farina di grano se preferisci la variante venezuelana. Il ripieno può essere adattato a ciò che hai a disposizione."}, "after": {"seo": {"title": "Arepa con Todo: ricetta tradizionale | Manual de Cocina", "robots": "index,follow", "description": "Ricetta dell'arepa farcita con carne sfilacciata, fagioli, formaggio, avocado e hogao. Impasto, cottura e farcitura passo dopo passo.", "faq": [{"q": "Posso sostituire la farina di mais precotta con pari farina di frumento?", "a": "No. Le due farine assorbono l'acqua e formano l'impasto in modo diverso. Qui usa farina di mais precotta; le arepas di frumento richiedono una ricetta specifica."}, {"q": "Perché l'arepa è dorata fuori e cruda dentro?", "a": "Il fuoco può essere troppo alto o il disco troppo spesso. Cuoci a fuoco medio come indicato e aprine una per controllare il centro prima di farcirla."}, {"q": "Quale ripieno posso usare senza carne?", "a": "Fagioli rifritti, avocado e formaggio sono opzioni semplici. Per una versione vegana ometti formaggio, burro, bacon e salse con ingredienti animali."}]}, "ingredients": [{"name": "Farina di mais precotta (farina di mais bianco o giallo)", "unit": "tazze di", "amount": "2", "group": "Per l'arepa"}, {"name": "Acqua tiepida", "unit": "tazze di", "amount": "2 1/2", "group": "Per l'arepa"}, {"name": "Sale", "unit": "cucchiaio di", "amount": "1", "group": "Per l'arepa"}, {"name": "Olio vegetale o burro per la cottura", "unit": "", "amount": "", "group": "Per l'arepa"}, {"name": "Carne sfilacciata (manzo, pollo o maiale)", "unit": "tazze", "amount": "2", "group": "Per il ripieno"}, {"name": "Fagioli fritti (frijoles refritos)", "unit": "tazza", "amount": "1", "group": "Per il ripieno"}, {"name": "Formaggio grattugiato (queso blanco o formaggio tipo mozzarella)", "unit": "tazza", "amount": "1", "group": "Per il ripieno"}, {"name": "Avocado a fette", "unit": "", "amount": "1", "group": "Per il ripieno"}, {"name": "Hogao (salsa di pomodoro e cipolla)", "unit": "tazza", "amount": "1/2", "group": "Per il ripieno"}, {"name": "Pancetta croccante (facoltativa)", "unit": "", "amount": "", "group": "Per il ripieno"}, {"name": "Salsa a scelta (ají, salsa tartara, guasacaca, ecc.)", "unit": "", "amount": "", "group": "Per il ripieno"}], "notes": "Questa preparazione usa farina di mais precotta. Non sostituirla con pari farina di frumento: le arepas di frumento richiedono una ricetta specifica. Aggiungi acqua gradualmente fino a ottenere un impasto lavorabile e fallo riposare 5 minuti. Conserva arepas cotte e ripieno separatamente in frigorifero; riscalda il ripieno prima di farcirle."}}, {"id": "688e4d13-c7bf-4441-8b15-990c132a7e4a", "public_path": "/ja/レシピアレパとすべて", "language": "ja", "before": {"seo": {"title": "アレパ・コン・トド:伝統レシピ | Manual de Cocina", "robots": "index,follow", "description": "ほぐし肉、豆、チーズ、アボカド、オガオを詰めた具だくさんアレパのレシピ。生地作りから焼き方、具材の詰め方までステップごとに解説。"}, "ingredients": [{"name": "アレパ生地用", "unit": "", "amount": ""}, {"name": "プレクックコーンフラワー(白または黄のとうもろこし粉)", "unit": "カップ", "amount": "2"}, {"name": "ベネズエラ風アレパを作る場合は小麦粉(パン用)。", "unit": "", "amount": ""}, {"name": "ぬるま湯", "unit": "カップ", "amount": "2 1/2"}, {"name": "塩", "unit": "大さじ", "amount": "1"}, {"name": "調理用の植物油またはバター", "unit": "", "amount": ""}, {"name": "具材用", "unit": "", "amount": ""}, {"name": "ほぐし肉(牛肉、鶏肉、豚肉のいずれか)", "unit": "", "amount": ""}, {"name": "リフライドビーンズ", "unit": "", "amount": ""}, {"name": "すりおろしチーズ(ケソブランコまたはモッツァレラタイプのチーズ)", "unit": "", "amount": ""}, {"name": "アボカド(薄切り)", "unit": "", "amount": ""}, {"name": "オガオ(トマトと玉ねぎのソース)", "unit": "", "amount": ""}, {"name": "カリカリベーコン(お好みで)", "unit": "", "amount": ""}, {"name": "お好みのソース(アヒ、タルタル、グアサカカなど)", "unit": "", "amount": ""}], "notes": "このレシピはコロンビア風・ベネズエラ風どちらのアレパにも対応しています。どちらもプレクックコーンフラワーを使うか、ベネズエラ風の小麦粉バージョンがお好みなら小麦粉を使ってください。具材は手元にあるものに合わせてアレンジできます。"}, "after": {"seo": {"title": "アレパ・コン・トド:伝統レシピ | Manual de Cocina", "robots": "index,follow", "description": "ほぐし肉、豆、チーズ、アボカド、オガオを詰めた具だくさんアレパのレシピ。生地作りから焼き方、具材の詰め方までステップごとに解説。", "faq": [{"q": "加熱済みとうもろこし粉を同量の小麦粉に替えられますか？", "a": "できません。小麦粉と加熱済みとうもろこし粉では吸水や生地の性質が異なります。このレシピでは指定のとうもろこし粉を使い、小麦のアレパは専用の配合で作ってください。"}, {"q": "表面は焼けても中が生なのはなぜ？", "a": "火が強すぎるか、生地が厚すぎる可能性があります。手順どおり中火で焼き、1枚を開いて中まで火が通ったか確認してから具を詰めます。"}, {"q": "肉なしの具材は何がおすすめですか？", "a": "リフライドビーンズ、アボカド、チーズが使えます。ヴィーガンにする場合はチーズ、バター、ベーコン、動物性材料入りのソースを省きます。"}]}, "ingredients": [{"name": "プレクックコーンフラワー(白または黄のとうもろこし粉)", "unit": "カップ", "amount": "2", "group": "アレパ生地用"}, {"name": "ぬるま湯", "unit": "カップ", "amount": "2 1/2", "group": "アレパ生地用"}, {"name": "塩", "unit": "大さじ", "amount": "1", "group": "アレパ生地用"}, {"name": "調理用の植物油またはバター", "unit": "", "amount": "", "group": "アレパ生地用"}, {"name": "ほぐし肉(牛肉、鶏肉、豚肉のいずれか)", "unit": "カップ", "amount": "2", "group": "具材用"}, {"name": "リフライドビーンズ", "unit": "カップ", "amount": "1", "group": "具材用"}, {"name": "すりおろしチーズ(ケソブランコまたはモッツァレラタイプのチーズ)", "unit": "カップ", "amount": "1", "group": "具材用"}, {"name": "アボカド(薄切り)", "unit": "", "amount": "1", "group": "具材用"}, {"name": "オガオ(トマトと玉ねぎのソース)", "unit": "カップ", "amount": "1/2", "group": "具材用"}, {"name": "カリカリベーコン(お好みで)", "unit": "", "amount": "", "group": "具材用"}, {"name": "お好みのソース(アヒ、タルタル、グアサカカなど)", "unit": "", "amount": "", "group": "具材用"}], "notes": "このレシピでは加熱済みとうもろこし粉を使います。小麦粉に同量で置き換えないでください。小麦のアレパには専用の配合が必要です。水を少しずつ加えて扱いやすい生地にし、5分休ませます。焼いたアレパと具は別々に冷蔵し、組み立てる前に具を温め直します。"}}, {"id": "4d37eeb6-e8b8-4705-835a-a62952868227", "public_path": "/pt/arepa-con-todo-receita", "language": "pt", "before": {"seo": {"title": "Arepa con Todo: receita tradicional | Manual de Cocina", "robots": "index,follow", "description": "Receita de arepa recheada com carne desfiada, feijão, queijo, abacate e hogao. Massa, cozimento e montagem passo a passo."}, "ingredients": [{"name": "Para a arepa", "unit": "", "amount": ""}, {"name": "Farinha de milho pré-cozida (farinha de milho branco ou amarelo)", "unit": "xícaras de", "amount": "2"}, {"name": "Farinha de trigo (pan), caso queira preparar uma arepa venezuelana.", "unit": "", "amount": ""}, {"name": "Água morna", "unit": "xícaras de", "amount": "2 1/2"}, {"name": "Sal", "unit": "colher de sopa de", "amount": "1"}, {"name": "Óleo vegetal ou manteiga para cozinhar", "unit": "", "amount": ""}, {"name": "Para o recheio", "unit": "", "amount": ""}, {"name": "Carne desfiada (pode usar carne bovina, frango ou porco)", "unit": "", "amount": ""}, {"name": "Feijão refrito", "unit": "", "amount": ""}, {"name": "Queijo ralado (queso blanco ou queijo tipo mussarela)", "unit": "", "amount": ""}, {"name": "Abacate em fatias", "unit": "", "amount": ""}, {"name": "Hogao (molho de tomate e cebola)", "unit": "", "amount": ""}, {"name": "Bacon crocante (opcional)", "unit": "", "amount": ""}, {"name": "Molho à sua escolha (ají, tártaro, guasacaca, etc.)", "unit": "", "amount": ""}], "notes": "Esta receita serve tanto para a versão colombiana quanto para a venezuelana da arepa: use farinha de milho pré-cozida para ambas, ou farinha de trigo se preferir a variante venezuelana. O recheio pode ser adaptado ao que você tiver disponível."}, "after": {"seo": {"title": "Arepa con Todo: receita tradicional | Manual de Cocina", "robots": "index,follow", "description": "Receita de arepa recheada com carne desfiada, feijão, queijo, abacate e hogao. Massa, cozimento e montagem passo a passo.", "faq": [{"q": "Posso trocar a farinha de milho pré-cozida por igual quantidade de trigo?", "a": "Não. As farinhas absorvem água e formam a massa de maneiras diferentes. Use milho pré-cozido nesta receita; arepas de trigo precisam de uma fórmula própria."}, {"q": "Por que a arepa doura e continua crua por dentro?", "a": "O fogo pode estar alto demais ou o disco muito grosso. Cozinhe em fogo médio como indicado e abra uma para conferir o centro antes de rechear."}, {"q": "Que recheio posso usar sem carne?", "a": "Feijão refrito, abacate e queijo são opções simples. Para uma versão vegana, omita queijo, manteiga, bacon e molhos com ingredientes animais."}]}, "ingredients": [{"name": "Farinha de milho pré-cozida (farinha de milho branco ou amarelo)", "unit": "xícaras de", "amount": "2", "group": "Para a arepa"}, {"name": "Água morna", "unit": "xícaras de", "amount": "2 1/2", "group": "Para a arepa"}, {"name": "Sal", "unit": "colher de sopa de", "amount": "1", "group": "Para a arepa"}, {"name": "Óleo vegetal ou manteiga para cozinhar", "unit": "", "amount": "", "group": "Para a arepa"}, {"name": "Carne desfiada (pode usar carne bovina, frango ou porco)", "unit": "xícaras", "amount": "2", "group": "Para o recheio"}, {"name": "Feijão refrito", "unit": "xícara", "amount": "1", "group": "Para o recheio"}, {"name": "Queijo ralado (queso blanco ou queijo tipo mussarela)", "unit": "xícara", "amount": "1", "group": "Para o recheio"}, {"name": "Abacate em fatias", "unit": "", "amount": "1", "group": "Para o recheio"}, {"name": "Hogao (molho de tomate e cebola)", "unit": "xícara", "amount": "1/2", "group": "Para o recheio"}, {"name": "Bacon crocante (opcional)", "unit": "", "amount": "", "group": "Para o recheio"}, {"name": "Molho à sua escolha (ají, tártaro, guasacaca, etc.)", "unit": "", "amount": "", "group": "Para o recheio"}], "notes": "Esta preparação usa farinha de milho pré-cozida. Não substitua pela mesma quantidade de trigo: arepas de trigo precisam de uma fórmula própria. Acrescente água aos poucos até obter uma massa maleável e deixe descansar 5 minutos. Guarde arepas cozidas e recheio separadamente na geladeira; reaqueça o recheio antes de montar."}}, {"id": "e7da4502-2064-4bd6-b275-56c9c0b54dd0", "public_path": "/receta-batido-de-frutas-con-crema", "language": "es", "before": {"seo": {"faq": [{"a": "Sí, sustitúyela por yogur natural o leche evaporada para una versión más ligera; el batido queda un poco menos espeso pero igual de sabroso.", "q": "¿Puedo hacer este batido sin crema de leche?"}, {"a": "Puedes usar la fruta que tengas disponible: papaya, melón, durazno o cualquier fruta madura funcionan bien en esta receta.", "q": "¿Qué frutas puedo usar si no tengo todas las indicadas?"}, {"a": "No necesariamente. Frutas como el plátano y el mango bien maduros ya aportan bastante dulzor; prueba el batido antes de decidir si necesita azúcar extra.", "q": "¿Es necesario añadir azúcar?"}, {"a": "Usa fruta congelada en lugar de fruta fresca con hielo, o reduce la cantidad de hielo triturado; así el batido queda cremoso sin diluirse.", "q": "¿Cómo logro que el batido quede bien espeso?"}], "title": "Batido de frutas con crema | Manual de Cocina", "robots": "index,follow", "description": "Batido cremoso de plátano, fresas, piña, mango, sandía, kiwi y uvas con crema de leche. Listo en minutos, perfecto para el calor."}}, "after": {"seo": {"faq": [{"q": "¿Puedo sustituir la crema de leche?", "a": "Sí. Puedes usar yogur natural o una alternativa vegetal adecuada para batir. Cambian la textura y el sabor; no se garantiza que cualquier sustituto aporte menos grasa o calorías."}, {"q": "¿Hace falta añadir azúcar?", "a": "No siempre. Prueba el batido después de licuarlo: el plátano y el mango maduros pueden aportar suficiente dulzor."}, {"q": "¿Cómo evito que quede aguado?", "a": "Usa parte de la fruta congelada y reduce el hielo. Añade líquido solo si hace falta para que la licuadora procese la mezcla."}], "title": "Batido de frutas con crema | Manual de Cocina", "robots": "index,follow", "description": "Batido cremoso de plátano, fresas, piña, mango, sandía, kiwi y uvas con crema de leche. Listo en minutos, perfecto para el calor."}}}, {"id": "1fb423f8-2ad0-47a1-99c9-a91642555aa7", "public_path": "/en/fruit-smoothie-recipe-with-cream", "language": "en", "before": {"seo": {"title": "Fruit Smoothie with Cream: easy, refreshing recipe | Manual de Cocina", "robots": "index,follow", "description": "Creamy smoothie with banana, strawberries, pineapple, mango, watermelon, kiwi and grapes blended with heavy cream. Ready in minutes."}}, "after": {"seo": {"title": "Fruit Smoothie with Cream: easy, refreshing recipe | Manual de Cocina", "robots": "index,follow", "description": "Creamy smoothie with banana, strawberries, pineapple, mango, watermelon, kiwi and grapes blended with heavy cream. Ready in minutes.", "faq": [{"q": "Can I replace the cream?", "a": "Yes. Use plain yogurt or a suitable plant-based blending alternative. Texture and flavor will change; a replacement is not necessarily lower in fat or calories."}, {"q": "Do I need to add sugar?", "a": "Not always. Taste after blending: ripe banana and mango may provide enough sweetness."}, {"q": "How do I stop it becoming watery?", "a": "Use some frozen fruit and reduce the ice. Add liquid only if needed for the blender to process the mixture."}]}}}, {"id": "d358573b-8cfa-4cf4-aa0a-cc78474360f0", "public_path": "/de/fruchtshake-mit-sahne-rezept", "language": "de", "before": {"seo": {"title": "Fruchtshake mit Sahne: einfaches, erfrischendes Rezept | Manual de Cocina", "robots": "index,follow", "description": "Cremiger Shake aus Banane, Erdbeeren, Ananas, Mango, Wassermelone, Kiwi und Trauben, gemixt mit Sahne. In wenigen Minuten fertig."}}, "after": {"seo": {"title": "Fruchtshake mit Sahne: einfaches, erfrischendes Rezept | Manual de Cocina", "robots": "index,follow", "description": "Cremiger Shake aus Banane, Erdbeeren, Ananas, Mango, Wassermelone, Kiwi und Trauben, gemixt mit Sahne. In wenigen Minuten fertig.", "faq": [{"q": "Kann ich die Sahne ersetzen?", "a": "Ja. Verwende Naturjoghurt oder eine zum Mixen geeignete pflanzliche Alternative. Konsistenz und Geschmack ändern sich; ein Ersatz enthält nicht automatisch weniger Fett oder Kalorien."}, {"q": "Muss Zucker dazu?", "a": "Nicht immer. Probiere den fertigen Shake: Reife Banane und Mango können genügend Süße liefern."}, {"q": "Wie verhindere ich einen wässrigen Shake?", "a": "Verwende einen Teil des Obstes gefroren und weniger Eis. Gib nur Flüssigkeit dazu, wenn der Mixer sie zum Verarbeiten braucht."}]}}}, {"id": "e3a78b33-8acd-4faf-8a2b-cb1be0e32d1c", "public_path": "/fr/recette-de-smoothie-aux-fruits-avec-creme", "language": "fr", "before": {"seo": {"title": "Smoothie de fruits à la crème | Manual de Cocina", "robots": "index,follow", "description": "Smoothie crémeux à la banane, fraises, ananas, mangue, pastèque, kiwi et raisins mixé avec de la crème. Prêt en quelques minutes."}}, "after": {"seo": {"title": "Smoothie de fruits à la crème | Manual de Cocina", "robots": "index,follow", "description": "Smoothie crémeux à la banane, fraises, ananas, mangue, pastèque, kiwi et raisins mixé avec de la crème. Prêt en quelques minutes.", "faq": [{"q": "Puis-je remplacer la crème ?", "a": "Oui, par du yaourt nature ou une alternative végétale adaptée au mixage. La texture et le goût changeront ; un substitut n'est pas forcément moins gras ou moins calorique."}, {"q": "Faut-il ajouter du sucre ?", "a": "Pas toujours. Goûtez après avoir mixé : la banane et la mangue mûres peuvent suffire à sucrer le mélange."}, {"q": "Comment éviter un résultat trop liquide ?", "a": "Utilisez une partie des fruits surgelés et réduisez les glaçons. N'ajoutez du liquide que si le mixeur en a besoin."}]}}}, {"id": "ba6014ea-b033-4f37-a948-8df00b181cae", "public_path": "/it/ricetta-frullato-di-frutta-con-panna", "language": "it", "before": {"seo": {"title": "Frullato di frutta con panna | Manual de Cocina", "robots": "index,follow", "description": "Frullato cremoso di banana, fragole, ananas, mango, anguria, kiwi e uva con panna. Pronto in pochi minuti."}}, "after": {"seo": {"title": "Frullato di frutta con panna | Manual de Cocina", "robots": "index,follow", "description": "Frullato cremoso di banana, fragole, ananas, mango, anguria, kiwi e uva con panna. Pronto in pochi minuti.", "faq": [{"q": "Posso sostituire la panna?", "a": "Sì, con yogurt bianco o un'alternativa vegetale adatta a essere frullata. Cambiano consistenza e sapore; un sostituto non contiene necessariamente meno grassi o calorie."}, {"q": "Devo aggiungere zucchero?", "a": "Non sempre. Assaggia dopo aver frullato: banana e mango maturi possono dare dolcezza sufficiente."}, {"q": "Come evito un frullato acquoso?", "a": "Usa parte della frutta congelata e riduci il ghiaccio. Aggiungi liquido solo se serve al frullatore per lavorare il composto."}]}}}, {"id": "4fc058ef-edec-4455-a2af-5067d69219c1", "public_path": "/ja/クリーム入りフルーツスムージーのレシピ", "language": "ja", "before": {"seo": {"title": "フルーツと生クリームのスムージー:簡単で爽やかなレシピ | Manual de Cocina", "robots": "index,follow", "description": "バナナ、いちご、パイナップル、マンゴー、スイカ、キウイ、ぶどうを生クリームと合わせた濃厚スムージー。数分で完成。"}}, "after": {"seo": {"title": "フルーツと生クリームのスムージー:簡単で爽やかなレシピ | Manual de Cocina", "robots": "index,follow", "description": "バナナ、いちご、パイナップル、マンゴー、スイカ、キウイ、ぶどうを生クリームと合わせた濃厚スムージー。数分で完成。", "faq": [{"q": "生クリームを替えられますか？", "a": "はい。プレーンヨーグルトや攪拌に適した植物性の代用品を使えます。食感や味は変わり、必ず低脂肪・低カロリーになるわけではありません。"}, {"q": "砂糖は必要ですか？", "a": "必須ではありません。攪拌した後で味をみます。よく熟したバナナとマンゴーだけで十分に甘くなることがあります。"}, {"q": "水っぽくならないコツは？", "a": "果物の一部を冷凍して使い、氷を減らします。ミキサーが回らないときだけ液体を足してください。"}]}}}, {"id": "55912d6c-d510-4671-94be-bae4690d0470", "public_path": "/pt/batida-de-frutas-com-creme-de-leite", "language": "pt", "before": {"seo": {"title": "Batida de frutas com creme de leite | Manual de Cocina", "robots": "index,follow", "description": "Batida cremosa de banana, morango, abacaxi, manga, melancia, kiwi e uva batida com creme de leite. Pronta em minutos."}}, "after": {"seo": {"title": "Batida de frutas com creme de leite | Manual de Cocina", "robots": "index,follow", "description": "Batida cremosa de banana, morango, abacaxi, manga, melancia, kiwi e uva batida com creme de leite. Pronta em minutos.", "faq": [{"q": "Posso substituir o creme de leite?", "a": "Sim, por iogurte natural ou uma alternativa vegetal adequada para bater. Textura e sabor mudam; a substituição não garante menos gordura ou calorias."}, {"q": "Preciso acrescentar açúcar?", "a": "Nem sempre. Prove depois de bater: banana e manga maduras podem dar doçura suficiente."}, {"q": "Como evito que fique aguado?", "a": "Use parte das frutas congeladas e reduza o gelo. Acrescente líquido apenas se o liquidificador precisar para bater a mistura."}]}}}, {"id": "e306a4bf-421c-4faa-9461-c1c0e11de127", "public_path": "/arroz-pilaf", "language": "es", "before": {"seo": {"faq": [{"a": "Casi siempre es por no enjuagar el arroz antes de cocinarlo (le sobra almidón) o por levantar la tapa durante la cocción, lo que deja escapar el vapor que cuece el grano de forma pareja.", "q": "¿Por qué mi arroz pilaf queda pegajoso en vez de suelto?"}, {"a": "Sí, pero necesita más líquido y más tiempo: usa unas 2 y 1/4 tazas de caldo por cada taza de arroz integral y cocina tapado unos 35-40 minutos en vez de 15-20.", "q": "¿Puedo usar arroz integral en lugar de blanco?"}, {"a": "Comino, cúrcuma o canela en cantidades pequeñas son las clásicas; también funciona bien un poco de pimentón dulce o unas hebras de azafrán si tienes.", "q": "¿Qué especias le quedan bien al arroz pilaf?"}, {"a": "Sí. Se conserva bien en la nevera hasta 4 días; recaliéntalo en una sartén con una cucharada de agua o caldo para que no se seque, hasta que humee por completo.", "q": "¿Se puede preparar con antelación?"}], "title": "Arroz pilaf: receta fácil paso a paso | Manual de Cocina", "robots": "index,follow", "description": "Receta de arroz pilaf con zanahoria y guisantes, saltado en mantequilla y cocido en caldo. Guarnición fácil, aromática y lista en 35 minutos."}}, "after": {"seo": {"faq": [{"q": "¿Cómo consigo un arroz pilaf suelto?", "a": "Enjuaga el arroz, escúrrelo bien y sofríelo como indica la receta. Cocina tapado sin remover y deja reposar antes de separar los granos con un tenedor."}, {"q": "¿Puedo usar arroz integral?", "a": "Sí, pero no conserva el mismo tiempo ni la misma proporción de caldo. Sigue las indicaciones del envase para arroz integral y ajusta el resto de la preparación."}, {"q": "¿Cómo hago una versión vegana?", "a": "Elige caldo de verduras y aceite de oliva en lugar de caldo de pollo y mantequilla. Comprueba también los ingredientes del caldo comercial."}], "title": "Arroz pilaf: receta fácil paso a paso | Manual de Cocina", "robots": "index,follow", "description": "Receta de arroz pilaf con zanahoria y guisantes, saltado en mantequilla y cocido en caldo. Guarnición fácil, aromática y lista en 35 minutos."}}}, {"id": "4850f21f-5661-45f8-b8e3-dd0d7b8bf644", "public_path": "/en/pilaf-rice", "language": "en", "before": {"seo": {"title": "Rice Pilaf: easy step-by-step recipe | Manual de Cocina", "robots": "index,follow", "description": "Rice pilaf recipe with carrot and peas, sautéed in butter and cooked in broth. Easy, aromatic side dish ready in 35 minutes."}}, "after": {"seo": {"title": "Rice Pilaf: easy step-by-step recipe | Manual de Cocina", "robots": "index,follow", "description": "Rice pilaf recipe with carrot and peas, sautéed in butter and cooked in broth. Easy, aromatic side dish ready in 35 minutes.", "faq": [{"q": "How do I keep pilaf rice fluffy?", "a": "Rinse and drain the rice well, then sauté it as directed. Cook covered without stirring and let it rest before fluffing with a fork."}, {"q": "Can I use brown rice?", "a": "Yes, but the cooking time and broth ratio will change. Follow the brown rice package directions and adapt the rest of the method."}, {"q": "How do I make it vegan?", "a": "Choose vegetable broth and olive oil instead of chicken broth and butter. Check the ingredients in store-bought broth too."}]}}}, {"id": "e089fa05-4f16-423f-9837-2b405be0b494", "public_path": "/de/pilawreis", "language": "de", "before": {"seo": {"title": "Reis-Pilaw: einfaches Schritt-für-Schritt-Rezept | Manual de Cocina", "robots": "index,follow", "description": "Reis-Pilaw-Rezept mit Karotte und Erbsen, in Butter angedünstet und in Brühe gegart. Einfache, aromatische Beilage, fertig in 35 Minuten."}}, "after": {"seo": {"title": "Reis-Pilaw: einfaches Schritt-für-Schritt-Rezept | Manual de Cocina", "robots": "index,follow", "description": "Reis-Pilaw-Rezept mit Karotte und Erbsen, in Butter angedünstet und in Brühe gegart. Einfache, aromatische Beilage, fertig in 35 Minuten.", "faq": [{"q": "Wie bleibt Pilawreis locker?", "a": "Spüle den Reis ab, lasse ihn gut abtropfen und dünste ihn wie beschrieben an. Gare ihn zugedeckt ohne Rühren und lasse ihn ruhen, bevor du die Körner auflockerst."}, {"q": "Kann ich Vollkornreis verwenden?", "a": "Ja, aber Garzeit und Brühenmenge ändern sich. Richte dich nach der Packungsangabe für Vollkornreis und passe die übrige Zubereitung an."}, {"q": "Wie wird das Gericht vegan?", "a": "Nimm Gemüsebrühe und Olivenöl statt Hühnerbrühe und Butter. Prüfe auch die Zutaten fertiger Brühe."}]}}}, {"id": "6429cada-7b0e-48f0-ac18-603fbf81f605", "public_path": "/fr/riz-pilaf", "language": "fr", "before": {"seo": {"title": "Riz pilaf : recette facile étape par étape | Manual de Cocina", "robots": "index,follow", "description": "Recette de riz pilaf à la carotte et aux petits pois, revenu au beurre et cuit dans du bouillon. Accompagnement facile et parfumé, prêt en 35 minutes."}}, "after": {"seo": {"title": "Riz pilaf : recette facile étape par étape | Manual de Cocina", "robots": "index,follow", "description": "Recette de riz pilaf à la carotte et aux petits pois, revenu au beurre et cuit dans du bouillon. Accompagnement facile et parfumé, prêt en 35 minutes.", "faq": [{"q": "Comment obtenir un riz pilaf bien détaché ?", "a": "Rincez et égouttez le riz, puis faites-le revenir comme indiqué. Cuisez à couvert sans remuer et laissez reposer avant d'égrener à la fourchette."}, {"q": "Puis-je utiliser du riz complet ?", "a": "Oui, mais le temps de cuisson et la quantité de bouillon changent. Suivez les indications du paquet de riz complet et adaptez la préparation."}, {"q": "Comment préparer une version végétalienne ?", "a": "Choisissez du bouillon de légumes et de l'huile d'olive plutôt que du bouillon de poulet et du beurre. Vérifiez aussi la composition du bouillon du commerce."}]}}}, {"id": "331ec414-0933-4555-a850-2beef50fb34a", "public_path": "/it/riso-pilaf", "language": "it", "before": {"seo": {"title": "Riso pilaf: ricetta facile passo dopo passo | Manual de Cocina", "robots": "index,follow", "description": "Ricetta del riso pilaf con carota e piselli, soffritto nel burro e cotto nel brodo. Contorno facile e aromatico, pronto in 35 minuti."}}, "after": {"seo": {"title": "Riso pilaf: ricetta facile passo dopo passo | Manual de Cocina", "robots": "index,follow", "description": "Ricetta del riso pilaf con carota e piselli, soffritto nel burro e cotto nel brodo. Contorno facile e aromatico, pronto in 35 minuti.", "faq": [{"q": "Come ottengo un riso pilaf sgranato?", "a": "Sciacqua il riso, scolalo bene e fallo insaporire come indicato. Cuoci coperto senza mescolare e lascia riposare prima di sgranare con una forchetta."}, {"q": "Posso usare riso integrale?", "a": "Sì, ma cambiano tempo di cottura e quantità di brodo. Segui le indicazioni sulla confezione del riso integrale e adatta il procedimento."}, {"q": "Come preparo una versione vegana?", "a": "Scegli brodo vegetale e olio d'oliva invece di brodo di pollo e burro. Controlla anche gli ingredienti del brodo confezionato."}]}}}, {"id": "50208613-ebc3-4567-b618-b81374b1830d", "public_path": "/ja/ピラフライス", "language": "ja", "before": {"seo": {"title": "アロス・ピラフ:簡単ステップバイステップレシピ | Manual de Cocina", "robots": "index,follow", "description": "にんじんとグリーンピース入りのアロス・ピラフのレシピ。バターで炒めてスープで炊き上げる、35分で作れる簡単で香り豊かな付け合わせ。"}}, "after": {"seo": {"title": "アロス・ピラフ:簡単ステップバイステップレシピ | Manual de Cocina", "robots": "index,follow", "description": "にんじんとグリーンピース入りのアロス・ピラフのレシピ。バターで炒めてスープで炊き上げる、35分で作れる簡単で香り豊かな付け合わせ。", "faq": [{"q": "ピラフをぱらっと仕上げるには？", "a": "米を洗ってよく水を切り、手順どおり炒めます。ふたをして混ぜずに炊き、蒸らしてからフォークでほぐします。"}, {"q": "玄米でも作れますか？", "a": "はい。ただし炊く時間とスープの量は変わります。玄米の袋に書かれた炊き方を基準に、ほかの工程を調整してください。"}, {"q": "ヴィーガンにするには？", "a": "チキンスープとバターの代わりに野菜スープとオリーブオイルを使います。市販のスープの原材料も確認してください。"}]}}}, {"id": "d3b517b7-957b-4a4c-bc69-e0b57498d288", "public_path": "/pt/arroz-pilaf-receita", "language": "pt", "before": {"seo": {"title": "Arroz pilaf: receita fácil passo a passo | Manual de Cocina", "robots": "index,follow", "description": "Receita de arroz pilaf com cenoura e ervilhas, refogado na manteiga e cozido no caldo. Acompanhamento fácil e aromático, pronto em 35 minutos."}}, "after": {"seo": {"title": "Arroz pilaf: receita fácil passo a passo | Manual de Cocina", "robots": "index,follow", "description": "Receita de arroz pilaf com cenoura e ervilhas, refogado na manteiga e cozido no caldo. Acompanhamento fácil e aromático, pronto em 35 minutos.", "faq": [{"q": "Como deixo o arroz pilaf soltinho?", "a": "Lave e escorra bem o arroz, depois refogue como indicado. Cozinhe tampado sem mexer e deixe descansar antes de soltar os grãos com um garfo."}, {"q": "Posso usar arroz integral?", "a": "Sim, mas o tempo e a proporção de caldo mudam. Siga as instruções da embalagem do arroz integral e adapte o restante do preparo."}, {"q": "Como faço uma versão vegana?", "a": "Escolha caldo de legumes e azeite no lugar de caldo de frango e manteiga. Confira também os ingredientes do caldo industrializado."}]}}}, {"id": "f7416832-d68f-4b41-a3c2-a4b47e02c9de", "public_path": "/barquitos-de-berenjenas-al-horno", "language": "es", "before": {"seo": {"faq": [{"a": "Para que se ablanden por dentro; si se rellenan crudas, es difícil que la pulpa restante se cocine bien durante el segundo horneado, y quedarían firmes en el centro.", "q": "¿Por qué se hornean las berenjenas antes de rellenarlas?"}, {"a": "Sí, sustituye la carne molida por champiñones picados, lentejas cocidas o un sustituto de carne vegetal, y sigue el mismo proceso de sofrito y salsa de tomate.", "q": "¿Puedo hacer esta receta vegetariana?"}, {"a": "La carne molida debe alcanzar una temperatura interna de 71°C (160°F) para consumirse de forma segura, según las recomendaciones del USDA.", "q": "¿A qué temperatura debo cocinar la carne molida?"}, {"a": "Deja un borde de aproximadamente 1 centímetro de pulpa alrededor de toda la cáscara y usa una cuchara pequeña para retirar el resto con cuidado, sin presionar demasiado los bordes.", "q": "¿Cómo evito que las berenjenas se rompan al vaciarlas?"}], "title": "Barquitos de berenjena al horno rellenos | Manual de Cocina", "robots": "index,follow", "description": "Receta de barquitos de berenjena rellenos de carne y salsa de tomate, gratinados con queso. Un entrante fácil y sabroso, horneado en dos tiempos."}, "notes": "<h3>Consejos</h3>\n<ul>\n<li>Hornea las mitades de berenjena vacías 10 minutos antes de rellenarlas: así se ablandan por dentro y no quedan crudas cuando termines el gratinado final.</li>\n<li>Deja un borde de al menos 1 cm de pulpa al vaciar la berenjena, para que la \"barca\" mantenga su forma y no se rompa al hornearla rellena.</li>\n<li>Pica la pulpa reservada y agrégala al relleno junto con la carne: aporta más sabor y evita desperdiciar parte de la berenjena.</li>\n</ul>\n<h3>Sustituciones</h3>\n<ul>\n<li>La carne molida de ternera puede cambiarse por pavo o pollo molido para una versión más ligera, o por champiñones picados o lentejas cocidas para una opción vegetariana.</li>\n<li>El queso mozzarella se puede reemplazar por cheddar, parmesano o una mezcla de quesos gratinables.</li>\n<li>Si no tienes tomate triturado en lata, puedes usar tomates frescos pelados y triturados o salsa de tomate natural sin azúcar añadida.</li>\n</ul>\n<h3>Conservación</h3>\n<ul>\n<li>Guarda los barquitos ya horneados en un recipiente hermético en el refrigerador hasta 3 días.</li>\n<li>Recalienta en el horno a 180°C durante 10-15 minutos para que el queso vuelva a gratinarse, en lugar de usar el microondas, que ablanda demasiado la berenjena.</li>\n<li>Si usas carne molida, asegúrate de cocinarla hasta que alcance una temperatura interna de 71°C (160°F) antes de rellenar y gratinar los barquitos.</li>\n</ul>\n<p class=\"md-sources\">Fuente: <a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-temperature-chart\">USDA FSIS – Safe Minimum Internal Temperature Chart</a></p>"}, "after": {"seo": {"faq": [{"q": "¿Por qué se hornean las berenjenas antes de rellenarlas?", "a": "El primer horneado ablanda la pulpa y facilita vaciarlas. Conserva un borde de aproximadamente 1 cm para que las mitades mantengan la forma."}, {"q": "¿Qué temperatura debe alcanzar el relleno de carne?", "a": "Compruébala con termómetro en el centro: al menos 71 °C para res o cerdo molidos, y 74 °C si usas pollo, pavo o una mezcla que contenga ave. El color no basta."}, {"q": "¿Puedo preparar un relleno vegetariano?", "a": "Sí. Sustituye la carne por lentejas cocidas o champiñones picados y sofríelos con las verduras. Para una versión vegana también necesitas reemplazar el queso."}], "title": "Barquitos de berenjena al horno rellenos | Manual de Cocina", "robots": "index,follow", "description": "Receta de barquitos de berenjena rellenos de carne y salsa de tomate, gratinados con queso. Un entrante fácil y sabroso, horneado en dos tiempos."}, "notes": "<h3>Consejos</h3>\n<ul>\n<li>Hornea las mitades de berenjena vacías 10 minutos antes de rellenarlas: así se ablandan por dentro y no quedan crudas cuando termines el gratinado final.</li>\n<li>Deja un borde de al menos 1 cm de pulpa al vaciar la berenjena, para que la \"barca\" mantenga su forma y no se rompa al hornearla rellena.</li>\n<li>Pica la pulpa reservada y agrégala al relleno junto con la carne: aporta más sabor y evita desperdiciar parte de la berenjena.</li>\n</ul>\n<h3>Sustituciones</h3>\n<ul>\n<li>La carne molida de ternera puede cambiarse por pavo o pollo molido para una versión más ligera, o por champiñones picados o lentejas cocidas para una opción vegetariana.</li>\n<li>El queso mozzarella se puede reemplazar por cheddar, parmesano o una mezcla de quesos gratinables.</li>\n<li>Si no tienes tomate triturado en lata, puedes usar tomates frescos pelados y triturados o salsa de tomate natural sin azúcar añadida.</li>\n</ul>\n<h3>Conservación</h3>\n<ul>\n<li>Guarda los barquitos ya horneados en un recipiente hermético en el refrigerador hasta 3 días.</li>\n<li>Recalienta en el horno a 180°C durante 10-15 minutos para que el queso vuelva a gratinarse, en lugar de usar el microondas, que ablanda demasiado la berenjena.</li>\n<li>Compruébala con termómetro en el centro: al menos 71 °C para res o cerdo molidos, y 74 °C si usas pollo, pavo o una mezcla que contenga ave. El color no basta.</li>\n</ul>\n<p class=\"md-sources\">Fuente: <a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-temperature-chart\">USDA FSIS – Safe Minimum Internal Temperature Chart</a></p>"}}, {"id": "84fdd27c-a9ea-4dd7-b295-d90951eb72f6", "public_path": "/en/baked-stuffed-eggplant-boats", "language": "en", "before": {"seo": {"title": "Baked Stuffed Eggplant Boats | Manual de Cocina", "robots": "index,follow", "description": "Eggplant boats stuffed with meat and tomato sauce, topped with melted cheese. An easy, tasty appetizer baked in two stages."}, "notes": "You can swap the ground meat for ground turkey or chicken for a lighter version. For a vegetarian filling, replace the meat with chopped mushrooms or cooked lentils."}, "after": {"seo": {"title": "Baked Stuffed Eggplant Boats | Manual de Cocina", "robots": "index,follow", "description": "Eggplant boats stuffed with meat and tomato sauce, topped with melted cheese. An easy, tasty appetizer baked in two stages.", "faq": [{"q": "Why bake the eggplants before filling them?", "a": "The first bake softens the flesh and makes scooping easier. Leave a border about 1 cm thick so the halves hold their shape."}, {"q": "What temperature should the meat filling reach?", "a": "Check the center with a food thermometer: at least 160°F (71°C) for ground beef or pork, and 165°F (74°C) for chicken, turkey or a mixture containing poultry. Color alone is not enough."}, {"q": "Can I make a vegetarian filling?", "a": "Yes. Replace the meat with cooked lentils or chopped mushrooms and sauté them with the vegetables. A vegan version also needs a cheese substitute."}]}, "notes": "<p>Yes. Replace the meat with cooked lentils or chopped mushrooms and sauté them with the vegetables. A vegan version also needs a cheese substitute.</p><p>Check the center with a food thermometer: at least 160°F (71°C) for ground beef or pork, and 165°F (74°C) for chicken, turkey or a mixture containing poultry. Color alone is not enough.</p>"}}, {"id": "8b68bcbc-0bd8-4263-8f75-1d8ba5a5cb3c", "public_path": "/de/gebackene-auberginenschiffchen", "language": "de", "before": {"seo": {"title": "Gefüllte Auberginenschiffchen aus dem Ofen | Manual de Cocina", "robots": "index,follow", "description": "Auberginenschiffchen gefüllt mit Fleisch und Tomatensauce, überbacken mit Käse. Eine einfache, leckere Vorspeise, in zwei Schritten gebacken."}, "notes": "Du kannst das Hackfleisch durch Puten- oder Hähnchenhackfleisch ersetzen für eine leichtere Version. Für eine vegetarische Füllung ersetze das Fleisch durch gehackte Champignons oder gekochte Linsen."}, "after": {"seo": {"title": "Gefüllte Auberginenschiffchen aus dem Ofen | Manual de Cocina", "robots": "index,follow", "description": "Auberginenschiffchen gefüllt mit Fleisch und Tomatensauce, überbacken mit Käse. Eine einfache, leckere Vorspeise, in zwei Schritten gebacken.", "faq": [{"q": "Warum werden die Auberginen vor dem Füllen gebacken?", "a": "Das Vorbacken macht das Fruchtfleisch weich und erleichtert das Aushöhlen. Lasse etwa 1 cm Rand stehen, damit die Hälften ihre Form behalten."}, {"q": "Welche Temperatur muss die Fleischfüllung erreichen?", "a": "Miss mit einem Küchenthermometer im Kern: mindestens 71 °C bei Rinder- oder Schweinehack, 74 °C bei Hähnchen, Pute oder einer Mischung mit Geflügel. Die Farbe allein genügt nicht."}, {"q": "Kann ich die Füllung vegetarisch machen?", "a": "Ja. Ersetze das Fleisch durch gekochte Linsen oder gehackte Pilze und brate sie mit dem Gemüse an. Für eine vegane Variante brauchst du auch einen Käseersatz."}]}, "notes": "<p>Ja. Ersetze das Fleisch durch gekochte Linsen oder gehackte Pilze und brate sie mit dem Gemüse an. Für eine vegane Variante brauchst du auch einen Käseersatz.</p><p>Miss mit einem Küchenthermometer im Kern: mindestens 71 °C bei Rinder- oder Schweinehack, 74 °C bei Hähnchen, Pute oder einer Mischung mit Geflügel. Die Farbe allein genügt nicht.</p>"}}, {"id": "f563dbc8-d3f5-4b0c-8ab3-038f49d6a35f", "public_path": "/fr/bateaux-aubergines-au-four", "language": "fr", "before": {"seo": {"title": "Barquettes d'aubergine farcies au four | Manual de Cocina", "robots": "index,follow", "description": "Barquettes d'aubergine farcies à la viande et à la sauce tomate, gratinées au fromage. Une entrée facile et savoureuse, cuite en deux temps."}, "notes": "Vous pouvez remplacer la viande hachée par de la dinde ou du poulet haché pour une version plus légère. Pour une garniture végétarienne, remplacez la viande par des champignons hachés ou des lentilles cuites."}, "after": {"seo": {"title": "Barquettes d'aubergine farcies au four | Manual de Cocina", "robots": "index,follow", "description": "Barquettes d'aubergine farcies à la viande et à la sauce tomate, gratinées au fromage. Une entrée facile et savoureuse, cuite en deux temps.", "faq": [{"q": "Pourquoi précuire les aubergines avant de les farcir ?", "a": "Cette cuisson attendrit la chair et facilite l'évidage. Gardez un bord d'environ 1 cm pour que les moitiés conservent leur forme."}, {"q": "Quelle température doit atteindre la farce de viande ?", "a": "Mesurez au centre avec un thermomètre : au moins 71 °C pour du bœuf ou du porc haché, 74 °C pour du poulet, de la dinde ou un mélange contenant de la volaille. La couleur ne suffit pas."}, {"q": "Peut-on préparer une farce végétarienne ?", "a": "Oui. Remplacez la viande par des lentilles cuites ou des champignons hachés, puis faites-les revenir avec les légumes. Pour une version végétalienne, remplacez aussi le fromage."}]}, "notes": "<p>Oui. Remplacez la viande par des lentilles cuites ou des champignons hachés, puis faites-les revenir avec les légumes. Pour une version végétalienne, remplacez aussi le fromage.</p><p>Mesurez au centre avec un thermomètre : au moins 71 °C pour du bœuf ou du porc haché, 74 °C pour du poulet, de la dinde ou un mélange contenant de la volaille. La couleur ne suffit pas.</p>"}}, {"id": "3dfaa0fb-522f-4ff7-98c5-5cddae43c50d", "public_path": "/it/barchette-di-melanzane-al-forno", "language": "it", "before": {"seo": {"title": "Barchette di melanzane ripiene al forno | Manual de Cocina", "robots": "index,follow", "description": "Barchette di melanzane ripiene di carne e salsa di pomodoro, gratinate con formaggio. Un antipasto facile e gustoso, cotto in due fasi."}, "notes": "Puoi sostituire la carne macinata con carne di tacchino o pollo per una versione più leggera. Per un ripieno vegetariano, sostituisci la carne con funghi tritati o lenticchie cotte."}, "after": {"seo": {"title": "Barchette di melanzane ripiene al forno | Manual de Cocina", "robots": "index,follow", "description": "Barchette di melanzane ripiene di carne e salsa di pomodoro, gratinate con formaggio. Un antipasto facile e gustoso, cotto in due fasi.", "faq": [{"q": "Perché cuocere le melanzane prima di farcirle?", "a": "La prima cottura ammorbidisce la polpa e rende più facile scavarle. Lascia un bordo di circa 1 cm perché le metà mantengano la forma."}, {"q": "Quale temperatura deve raggiungere il ripieno di carne?", "a": "Misura al centro con un termometro: almeno 71 °C per manzo o maiale macinati, 74 °C per pollo, tacchino o miscele con pollame. Il colore da solo non basta."}, {"q": "Posso preparare un ripieno vegetariano?", "a": "Sì. Sostituisci la carne con lenticchie cotte o funghi tritati e falli insaporire con le verdure. Per una versione vegana devi sostituire anche il formaggio."}]}, "notes": "<p>Sì. Sostituisci la carne con lenticchie cotte o funghi tritati e falli insaporire con le verdure. Per una versione vegana devi sostituire anche il formaggio.</p><p>Misura al centro con un termometro: almeno 71 °C per manzo o maiale macinati, 74 °C per pollo, tacchino o miscele con pollame. Il colore da solo non basta.</p>"}}, {"id": "c77b6523-e570-4beb-98a2-d1c096431245", "public_path": "/ja/焼きナスの舟", "language": "ja", "before": {"seo": {"title": "オーブン焼きなすボート:ひき肉とチーズのレシピ | Manual de Cocina", "robots": "index,follow", "description": "ひき肉とトマトソースを詰めてチーズをのせたオーブン焼きなすボートのレシピ。前菜やライトな夕食にぴったりの一品。"}, "notes": "ひき肉の代わりに鶏ひき肉や七面鳥のひき肉を使うと、より軽い仕上がりになります。ベジタリアン向けには、肉の代わりにみじん切りのマッシュルームや煮たレンズ豆を使うのもおすすめです。"}, "after": {"seo": {"title": "オーブン焼きなすボート:ひき肉とチーズのレシピ | Manual de Cocina", "robots": "index,follow", "description": "ひき肉とトマトソースを詰めてチーズをのせたオーブン焼きなすボートのレシピ。前菜やライトな夕食にぴったりの一品。", "faq": [{"q": "なぜ詰める前になすを焼くのですか？", "a": "最初に焼くと果肉が柔らかくなり、くり抜きやすくなります。形が崩れないよう、周囲に約1cmの果肉を残します。"}, {"q": "肉の詰め物は何度まで加熱しますか？", "a": "中心を食品用温度計で測ります。牛・豚ひき肉は最低71°C、鶏・七面鳥やそれらを含む混合肉は74°Cが目安です。色だけで判断しないでください。"}, {"q": "ベジタリアンの詰め物にできますか？", "a": "はい。肉を煮たレンズ豆や刻んだマッシュルームに替え、野菜と一緒に炒めます。ヴィーガンにする場合はチーズも植物性のものに替えます。"}]}, "notes": "<p>はい。肉を煮たレンズ豆や刻んだマッシュルームに替え、野菜と一緒に炒めます。ヴィーガンにする場合はチーズも植物性のものに替えます。</p><p>中心を食品用温度計で測ります。牛・豚ひき肉は最低71°C、鶏・七面鳥やそれらを含む混合肉は74°Cが目安です。色だけで判断しないでください。</p>"}}, {"id": "c4bcd53e-b10b-4dce-a8d3-345485de73dd", "public_path": "/pt/barquinhos-de-berinjela-ao-forno", "language": "pt", "before": {"seo": {"title": "Barquinhos de berinjela recheados ao forno | Manual de Cocina", "robots": "index,follow", "description": "Barquinhos de berinjela recheados com carne e molho de tomate, gratinados com queijo. Uma entrada fácil e saborosa, assada em duas etapas."}, "notes": "Você pode substituir a carne moída por peru ou frango moído para uma versão mais leve. Para um recheio vegetariano, troque a carne por cogumelos picados ou lentilhas cozidas."}, "after": {"seo": {"title": "Barquinhos de berinjela recheados ao forno | Manual de Cocina", "robots": "index,follow", "description": "Barquinhos de berinjela recheados com carne e molho de tomate, gratinados com queijo. Uma entrada fácil e saborosa, assada em duas etapas.", "faq": [{"q": "Por que assar as berinjelas antes de rechear?", "a": "A primeira etapa amacia a polpa e facilita retirá-la. Deixe uma borda de aproximadamente 1 cm para as metades manterem a forma."}, {"q": "Que temperatura o recheio de carne deve atingir?", "a": "Meça no centro com termômetro: pelo menos 71 °C para carne bovina ou suína moída, e 74 °C para frango, peru ou misturas com aves. A cor sozinha não basta."}, {"q": "Posso fazer um recheio vegetariano?", "a": "Sim. Substitua a carne por lentilhas cozidas ou cogumelos picados e refogue com os legumes. Para uma versão vegana, substitua também o queijo."}]}, "notes": "<p>Sim. Substitua a carne por lentilhas cozidas ou cogumelos picados e refogue com os legumes. Para uma versão vegana, substitua também o queijo.</p><p>Meça no centro com termômetro: pelo menos 71 °C para carne bovina ou suína moída, e 74 °C para frango, peru ou misturas com aves. A cor sozinha não basta.</p>"}}, {"id": "52fbd60c-9d33-481f-8d85-3eaaca0f220b", "public_path": "/receta-de-ajiaco", "language": "es", "before": {"seo": {"faq": [{"a": "Cada papa cumple una función: la papa criolla se deshace y espesa el caldo, la papa pastusa aporta cuerpo, y una papa firme como la sabanera mantiene trozos reconocibles en la sopa.", "q": "¿Por qué el ajiaco necesita tres tipos de papa?"}, {"a": "Las guascas son una hierba aromática típica de la sabana de Bogotá que le da al ajiaco su sabor distintivo. Se consiguen secas en tiendas de productos colombianos; sin ellas, la sopa sigue siendo sabrosa pero deja de ser un ajiaco tradicional.", "q": "¿Qué son las guascas y puedo omitirlas?"}, {"a": "Se sirve caliente, con la mazorca dentro o aparte, y cada comensal agrega a su plato crema de leche, alcaparras y aguacate al gusto.", "q": "¿Cómo se sirve tradicionalmente el ajiaco?"}, {"a": "Sí, incluso mejora de un día para otro. Guárdalo en el refrigerador hasta 3-4 días y recaliéntalo a fuego medio, añadiendo los acompañamientos frescos justo antes de servir.", "q": "¿Se puede preparar el ajiaco con anticipación?"}], "title": "Ajiaco colombiano: receta tradicional | Manual de Cocina", "robots": "index,follow", "description": "Receta de ajiaco colombiano con pollo, mazorca, guascas y tres tipos de papa. Cocción, textura, servicio, conservación y preguntas frecuentes."}}, "after": {"seo": {"faq": [{"q": "¿Por qué se usan varios tipos de papa?", "a": "Una parte se deshace y espesa el caldo, mientras otra conserva trozos. La receta combina papa criolla, pastusa o blanca, y sabanera u otra variedad firme."}, {"q": "¿Qué son las guascas?", "a": "Son la hierba que aporta el aroma característico del ajiaco bogotano. Puedes buscarlas secas en tiendas colombianas; otra hierba no reproduce exactamente su sabor."}, {"q": "¿Cuándo añado la crema, las alcaparras y el aguacate?", "a": "Al servir, como acompañamientos separados. Así cada persona ajusta su plato y el aguacate no se cocina dentro de la olla."}], "title": "Ajiaco colombiano: receta tradicional | Manual de Cocina", "robots": "index,follow", "description": "Receta de ajiaco colombiano con pollo, mazorca, guascas y tres tipos de papa. Cocción, textura, servicio, conservación y preguntas frecuentes."}}}, {"id": "49a2845e-5eaf-47b4-a66b-7b6dde3f0048", "public_path": "/en/ajiaco-recipe", "language": "en", "before": {"seo": {"title": "Colombian Ajiaco: Traditional Recipe | Manual de Cocina", "robots": "index,follow", "description": "Colombian ajiaco recipe with chicken, corn, guascas and three kinds of potato. Cooking, texture, serving and storage."}}, "after": {"seo": {"title": "Colombian Ajiaco: Traditional Recipe | Manual de Cocina", "robots": "index,follow", "description": "Colombian ajiaco recipe with chicken, corn, guascas and three kinds of potato. Cooking, texture, serving and storage.", "faq": [{"q": "Why use different kinds of potato?", "a": "Some break down and thicken the broth while others stay in pieces. This recipe combines papa criolla, pastusa or white potatoes, and sabanera or another firm variety."}, {"q": "What are guascas?", "a": "Guascas are the herb that gives Bogotá-style ajiaco its characteristic aroma. Look for dried guascas in Colombian shops; another herb will not reproduce the exact flavor."}, {"q": "When should I add cream, capers and avocado?", "a": "Serve them separately as toppings. Each person can adjust their bowl and the avocado stays out of the cooking pot."}]}}}, {"id": "4324c03a-abdd-44c5-9570-99c91bb4c237", "public_path": "/de/ajiaco-rezept", "language": "de", "before": {"seo": {"title": "Kolumbianisches Ajiaco: Traditionelles Rezept | Manual de Cocina", "robots": "index,follow", "description": "Rezept für kolumbianisches Ajiaco mit Hühnchen, Maiskolben, Guascas und drei Kartoffelsorten. Zubereitung, Konsistenz, Servieren und Aufbewahrung."}}, "after": {"seo": {"title": "Kolumbianisches Ajiaco: Traditionelles Rezept | Manual de Cocina", "robots": "index,follow", "description": "Rezept für kolumbianisches Ajiaco mit Hühnchen, Maiskolben, Guascas und drei Kartoffelsorten. Zubereitung, Konsistenz, Servieren und Aufbewahrung.", "faq": [{"q": "Warum werden verschiedene Kartoffelsorten verwendet?", "a": "Ein Teil zerfällt und bindet die Brühe, andere Kartoffeln bleiben stückig. Das Rezept kombiniert Papa criolla, Pastusa oder weiße Kartoffeln sowie Sabanera oder eine andere festkochende Sorte."}, {"q": "Was sind Guascas?", "a": "Guascas sind das Kraut, das Ajiaco aus Bogotá sein typisches Aroma gibt. Du findest es getrocknet in kolumbianischen Geschäften; andere Kräuter ersetzen den Geschmack nicht genau."}, {"q": "Wann kommen Sahne, Kapern und Avocado dazu?", "a": "Reiche sie beim Servieren getrennt dazu. So kann jeder seinen Teller anpassen und die Avocado wird nicht im Topf mitgekocht."}]}}}, {"id": "8bdf411b-5842-484c-8398-83c771c3fa08", "public_path": "/fr/ajiaco-recette", "language": "fr", "before": {"seo": {"title": "Ajiaco colombien : recette traditionnelle | Manual de Cocina", "robots": "index,follow", "description": "Recette d'ajiaco colombien au poulet, maïs, guascas et trois variétés de pommes de terre. Cuisson, texture, service et conservation."}}, "after": {"seo": {"title": "Ajiaco colombien : recette traditionnelle | Manual de Cocina", "robots": "index,follow", "description": "Recette d'ajiaco colombien au poulet, maïs, guascas et trois variétés de pommes de terre. Cuisson, texture, service et conservation.", "faq": [{"q": "Pourquoi utiliser plusieurs variétés de pommes de terre ?", "a": "Certaines se défont pour épaissir le bouillon, d'autres restent en morceaux. La recette associe papa criolla, pastusa ou pomme de terre blanche, et sabanera ou une autre variété ferme."}, {"q": "Que sont les guascas ?", "a": "C'est l'herbe qui donne son parfum caractéristique à l'ajiaco de Bogotá. Cherchez-la séchée dans les épiceries colombiennes ; une autre herbe n'en reproduit pas exactement le goût."}, {"q": "Quand ajouter la crème, les câpres et l'avocat ?", "a": "Servez-les séparément en accompagnement. Chacun peut ainsi ajuster son assiette et l'avocat ne cuit pas dans la marmite."}]}}}, {"id": "ca08844b-5e00-4a0d-9884-00205545c74a", "public_path": "/it/ajiaco-ricetta", "language": "it", "before": {"seo": {"title": "Ajiaco colombiano: ricetta tradizionale | Manual de Cocina", "robots": "index,follow", "description": "Ricetta dell'ajiaco colombiano con pollo, mais, guasca e diverse varietà di patate. Preparazione, consistenza, conservazione e FAQ."}}, "after": {"seo": {"title": "Ajiaco colombiano: ricetta tradizionale | Manual de Cocina", "robots": "index,follow", "description": "Ricetta dell'ajiaco colombiano con pollo, mais, guasca e diverse varietà di patate. Preparazione, consistenza, conservazione e FAQ.", "faq": [{"q": "Perché si usano diversi tipi di patate?", "a": "Alcune si disfano e addensano il brodo, altre restano a pezzi. La ricetta unisce papa criolla, pastusa o patate bianche, e sabanera o un'altra varietà soda."}, {"q": "Che cosa sono le guascas?", "a": "Sono l'erba che dà all'ajiaco di Bogotá il suo aroma caratteristico. Cercale essiccate nei negozi colombiani; un'altra erba non ne riproduce esattamente il sapore."}, {"q": "Quando aggiungo panna, capperi e avocado?", "a": "Servili separatamente come accompagnamenti. Ognuno può regolare il proprio piatto e l'avocado non viene cotto nella pentola."}]}}}, {"id": "46488da8-104a-4400-a9ea-d134488866eb", "public_path": "/ja/アヒアコレシピ", "language": "ja", "before": {"seo": {"title": "コロンビア風アヒアコ：伝統レシピ | Manual de Cocina", "robots": "index,follow", "description": "鶏肉、とうもろこし、グアスカス、三種のじゃがいもを使ったコロンビア風アヒアコのレシピ。調理法、食感、盛り付け、保存方法を紹介。"}}, "after": {"seo": {"title": "コロンビア風アヒアコ：伝統レシピ | Manual de Cocina", "robots": "index,follow", "description": "鶏肉、とうもろこし、グアスカス、三種のじゃがいもを使ったコロンビア風アヒアコのレシピ。調理法、食感、盛り付け、保存方法を紹介。", "faq": [{"q": "なぜ数種類のじゃがいもを使うのですか？", "a": "煮崩れてスープにとろみをつけるものと、形を残すものを組み合わせます。このレシピではクリオージャ種、パストゥサ種または白いじゃがいも、サバネラ種などの崩れにくい品種を使います。"}, {"q": "グアスカスとは何ですか？", "a": "ボゴタのアヒアコ特有の香りをつけるハーブです。コロンビア食材店などで乾燥品を探してください。ほかのハーブでは同じ風味にはなりません。"}, {"q": "クリーム、ケッパー、アボカドはいつ加えますか？", "a": "食べるときに別添えにします。それぞれ好みの量を加えられ、アボカドを鍋で煮る必要もありません。"}]}}}, {"id": "3fe4e81e-f100-42ad-9ed2-11cfe05dacd4", "public_path": "/pt/receita-de-ajiaco-colombiano", "language": "pt", "before": {"seo": {"title": "Ajiaco colombiano: receita tradicional | Manual de Cocina", "robots": "index,follow", "description": "Receita de ajiaco colombiano com frango, milho, guascas e três tipos de batata. Cozimento, textura, modo de servir e conservação."}}, "after": {"seo": {"title": "Ajiaco colombiano: receita tradicional | Manual de Cocina", "robots": "index,follow", "description": "Receita de ajiaco colombiano com frango, milho, guascas e três tipos de batata. Cozimento, textura, modo de servir e conservação.", "faq": [{"q": "Por que usar diferentes tipos de batata?", "a": "Parte se desfaz e engrossa o caldo, enquanto outra mantém pedaços. A receita combina papa criolla, pastusa ou batata branca, e sabanera ou outra variedade firme."}, {"q": "O que são guascas?", "a": "É a erva que dá o aroma característico ao ajiaco de Bogotá. Procure a versão seca em lojas colombianas; outra erva não reproduz exatamente o sabor."}, {"q": "Quando acrescento creme, alcaparras e abacate?", "a": "Sirva separadamente como acompanhamentos. Assim cada pessoa ajusta o prato e o abacate não cozinha dentro da panela."}]}}}, {"id": "4b357e5e-f115-4f36-a9fa-6a8866ee8e34", "public_path": "/porra-antequerana-receta", "language": "es", "before": {"seo": {"title": "Porra antequerana: receta espesa y fácil | Manual de Cocina", "description": "Cómo hacer porra antequerana con tomate, pan, pimiento verde, ajo y aceite de oliva. Proporciones, textura cremosa, enfriado y guarnición opcional.", "image_variants": ["/recetas/porra-antequerana/portada-1x1.webp", "/recetas/porra-antequerana/portada-4x3.webp", "/recetas/porra-antequerana/portada-16x9.webp"]}}, "after": {"seo": {"title": "Porra antequerana: receta espesa y fácil | Manual de Cocina", "description": "Cómo hacer porra antequerana con tomate, pan, pimiento verde, ajo y aceite de oliva. Proporciones, textura cremosa, enfriado y guarnición opcional.", "image_variants": ["/recetas/porra-antequerana/portada-1x1.webp", "/recetas/porra-antequerana/portada-4x3.webp", "/recetas/porra-antequerana/portada-16x9.webp"], "faq": [{"q": "¿La porra antequerana se sirve caliente o fría?", "a": "Fría. Tápala y déjala en la nevera al menos una hora, como indica la preparación. Remueve antes de servir y añade la guarnición al final."}, {"q": "¿Cómo arreglo una porra demasiado líquida?", "a": "Añade un poco más de pan, deja que se hidrate y vuelve a triturar. Incorpóralo poco a poco para no dejarla excesivamente espesa y ajusta la sal al final."}, {"q": "¿Puedo servirla sin huevo ni jamón?", "a": "Sí. Ambos son guarniciones opcionales; la crema base no los necesita. El pan contiene gluten, salvo que uses una alternativa sin gluten adecuada."}]}}}, {"id": "4a7fd514-7523-46a7-964a-994234eba6c2", "public_path": "/en/porra-antequerana-recipe", "language": "en", "before": {"seo": {"title": "Porra antequerana recipe: thick chilled tomato soup | Manual de Cocina", "description": "Make porra antequerana with tomato, bread, green pepper and olive oil. Clear proportions, a thick spoonable texture, chilling time and optional toppings.", "image_variants": ["/recetas/porra-antequerana/portada-1x1.webp", "/recetas/porra-antequerana/portada-4x3.webp", "/recetas/porra-antequerana/portada-16x9.webp"]}}, "after": {"seo": {"title": "Porra antequerana recipe: thick chilled tomato soup | Manual de Cocina", "description": "Make porra antequerana with tomato, bread, green pepper and olive oil. Clear proportions, a thick spoonable texture, chilling time and optional toppings.", "image_variants": ["/recetas/porra-antequerana/portada-1x1.webp", "/recetas/porra-antequerana/portada-4x3.webp", "/recetas/porra-antequerana/portada-16x9.webp"], "faq": [{"q": "Is porra antequerana served hot or cold?", "a": "Cold. Cover and refrigerate for at least one hour as directed. Stir before serving and add the toppings at the end."}, {"q": "How do I fix porra that is too thin?", "a": "Add a little more bread, let it absorb liquid and blend again. Add it gradually to avoid making the soup too thick, then adjust the salt."}, {"q": "Can I serve it without egg or ham?", "a": "Yes. Both are optional toppings; the base does not need them. The bread contains gluten unless you choose a suitable gluten-free alternative."}]}}}, {"id": "42d31507-ed5c-48eb-b661-6a10710cd21c", "public_path": "/de/porra-antequerana-rezept", "language": "de", "before": {"seo": {"title": "Porra Antequerana: Rezept für kalte Tomatencreme | Manual de Cocina", "description": "Porra Antequerana mit Tomaten, Brot, grüner Paprika und Olivenöl zubereiten: Mengen, dicke Konsistenz, Kühlzeit und optionale Garnitur.", "image_variants": ["/recetas/porra-antequerana/portada-1x1.webp", "/recetas/porra-antequerana/portada-4x3.webp", "/recetas/porra-antequerana/portada-16x9.webp"]}}, "after": {"seo": {"title": "Porra Antequerana: Rezept für kalte Tomatencreme | Manual de Cocina", "description": "Porra Antequerana mit Tomaten, Brot, grüner Paprika und Olivenöl zubereiten: Mengen, dicke Konsistenz, Kühlzeit und optionale Garnitur.", "image_variants": ["/recetas/porra-antequerana/portada-1x1.webp", "/recetas/porra-antequerana/portada-4x3.webp", "/recetas/porra-antequerana/portada-16x9.webp"], "faq": [{"q": "Wird Porra antequerana warm oder kalt serviert?", "a": "Kalt. Decke sie ab und stelle sie wie beschrieben mindestens eine Stunde in den Kühlschrank. Rühre vor dem Servieren um und gib die Garnitur erst zum Schluss dazu."}, {"q": "Was hilft, wenn die Porra zu flüssig ist?", "a": "Gib etwas Brot dazu, lasse es Flüssigkeit aufnehmen und püriere erneut. Arbeite in kleinen Mengen, damit die Creme nicht zu dick wird, und schmecke zuletzt mit Salz ab."}, {"q": "Kann ich Ei und Schinken weglassen?", "a": "Ja. Beides ist eine optionale Garnitur und gehört nicht zwingend in die Creme. Das Brot enthält Gluten, sofern du keine geeignete glutenfreie Alternative verwendest."}]}}}, {"id": "bb7b17f6-76aa-4b63-9c5d-f9623984618e", "public_path": "/fr/recette-porra-antequerana", "language": "fr", "before": {"seo": {"title": "Porra antequerana : recette de soupe froide épaisse | Manual de Cocina", "description": "Préparez une porra antequerana à la tomate et au pain : proportions, texture crémeuse, émulsion à l’huile d’olive et garniture facultative.", "image_variants": ["/recetas/porra-antequerana/portada-1x1.webp", "/recetas/porra-antequerana/portada-4x3.webp", "/recetas/porra-antequerana/portada-16x9.webp"]}}, "after": {"seo": {"title": "Porra antequerana : recette de soupe froide épaisse | Manual de Cocina", "description": "Préparez une porra antequerana à la tomate et au pain : proportions, texture crémeuse, émulsion à l’huile d’olive et garniture facultative.", "image_variants": ["/recetas/porra-antequerana/portada-1x1.webp", "/recetas/porra-antequerana/portada-4x3.webp", "/recetas/porra-antequerana/portada-16x9.webp"], "faq": [{"q": "La porra antequerana se sert-elle chaude ou froide ?", "a": "Froide. Couvrez et réfrigérez au moins une heure comme indiqué. Remuez avant de servir et ajoutez la garniture au dernier moment."}, {"q": "Comment rattraper une porra trop liquide ?", "a": "Ajoutez un peu de pain, laissez-le s'imbiber puis mixez de nouveau. Procédez progressivement pour ne pas trop épaissir la crème, puis rectifiez le sel."}, {"q": "Peut-on la servir sans œuf ni jambon ?", "a": "Oui. Ce sont des garnitures facultatives, inutiles à la crème de base. Le pain contient du gluten, sauf si vous utilisez une alternative sans gluten adaptée."}]}}}, {"id": "4dce08c1-b6a6-4f90-b7f8-c37ea3573728", "public_path": "/it/porra-antequerana-ricetta", "language": "it", "before": {"seo": {"title": "Porra antequerana: ricetta cremosa andalusa | Manual de Cocina", "description": "Come preparare la porra antequerana con pomodori, pane e peperone verde: dosi, consistenza densa, emulsione con olio e guarnizione facoltativa.", "image_variants": ["/recetas/porra-antequerana/portada-1x1.webp", "/recetas/porra-antequerana/portada-4x3.webp", "/recetas/porra-antequerana/portada-16x9.webp"]}}, "after": {"seo": {"title": "Porra antequerana: ricetta cremosa andalusa | Manual de Cocina", "description": "Come preparare la porra antequerana con pomodori, pane e peperone verde: dosi, consistenza densa, emulsione con olio e guarnizione facoltativa.", "image_variants": ["/recetas/porra-antequerana/portada-1x1.webp", "/recetas/porra-antequerana/portada-4x3.webp", "/recetas/porra-antequerana/portada-16x9.webp"], "faq": [{"q": "La porra antequerana si serve calda o fredda?", "a": "Fredda. Coprila e mettila in frigorifero per almeno un'ora, come indicato. Mescola prima di servire e aggiungi la guarnizione alla fine."}, {"q": "Come correggo una porra troppo liquida?", "a": "Aggiungi poco pane, fallo ammorbidire e frulla ancora. Procedi gradualmente per non rendere la crema troppo densa e regola il sale alla fine."}, {"q": "Posso servirla senza uova e prosciutto?", "a": "Sì. Sono guarnizioni facoltative e non servono alla crema di base. Il pane contiene glutine, salvo l'uso di un'alternativa senza glutine adatta."}]}}}, {"id": "84a467a1-c9b4-4002-93f8-b6421b115090", "public_path": "/ja/ポッラ・アンテケラナ・レシピ", "language": "ja", "before": {"seo": {"title": "ポラ・アンテケラーナのレシピ｜濃厚な冷製トマトスープ | Manual de Cocina", "description": "トマトとパンで作るアンダルシアの冷製スープ。材料の分量、濃厚に仕上げる混ぜ方、冷やす時間と盛りつけを紹介します。", "image_variants": ["/recetas/porra-antequerana/portada-1x1.webp", "/recetas/porra-antequerana/portada-4x3.webp", "/recetas/porra-antequerana/portada-16x9.webp"]}}, "after": {"seo": {"title": "ポラ・アンテケラーナのレシピ｜濃厚な冷製トマトスープ | Manual de Cocina", "description": "トマトとパンで作るアンダルシアの冷製スープ。材料の分量、濃厚に仕上げる混ぜ方、冷やす時間と盛りつけを紹介します。", "image_variants": ["/recetas/porra-antequerana/portada-1x1.webp", "/recetas/porra-antequerana/portada-4x3.webp", "/recetas/porra-antequerana/portada-16x9.webp"], "faq": [{"q": "ポラ・アンテケラーナは温かくして食べますか？", "a": "冷たくして食べます。手順どおり、ふたをして冷蔵庫で最低1時間冷やします。食べる前に混ぜ、トッピングは最後にのせます。"}, {"q": "水っぽいときはどうすればよいですか？", "a": "パンを少し足して水分を吸わせ、もう一度攪拌します。固くなりすぎないよう少しずつ加え、最後に塩で味を調えます。"}, {"q": "卵やハムなしでも食べられますか？", "a": "はい。どちらも任意のトッピングで、基本のスープには必要ありません。パンにはグルテンが含まれるため、避ける場合は適したグルテンフリー製品を使います。"}]}}}, {"id": "b908eece-0754-40fe-8476-a75f42e8ca19", "public_path": "/pt/receita-de-porra-antequerana", "language": "pt", "before": {"seo": {"title": "Porra antequerana: receita de creme frio espanhol | Manual de Cocina", "description": "Faça porra antequerana com tomate, pão, pimentão verde e azeite: quantidades, textura espessa, tempo de geladeira e cobertura opcional.", "image_variants": ["/recetas/porra-antequerana/portada-1x1.webp", "/recetas/porra-antequerana/portada-4x3.webp", "/recetas/porra-antequerana/portada-16x9.webp"]}}, "after": {"seo": {"title": "Porra antequerana: receita de creme frio espanhol | Manual de Cocina", "description": "Faça porra antequerana com tomate, pão, pimentão verde e azeite: quantidades, textura espessa, tempo de geladeira e cobertura opcional.", "image_variants": ["/recetas/porra-antequerana/portada-1x1.webp", "/recetas/porra-antequerana/portada-4x3.webp", "/recetas/porra-antequerana/portada-16x9.webp"], "faq": [{"q": "A porra antequerana é servida quente ou fria?", "a": "Fria. Tampe e leve à geladeira por pelo menos uma hora, como indicado. Mexa antes de servir e acrescente os acompanhamentos no final."}, {"q": "Como corrijo uma porra muito líquida?", "a": "Acrescente um pouco de pão, espere hidratar e bata novamente. Faça isso aos poucos para não engrossar demais e ajuste o sal no final."}, {"q": "Posso servir sem ovo e presunto?", "a": "Sim. São acompanhamentos opcionais e não fazem parte da base da sopa. O pão contém glúten, a menos que você use uma alternativa sem glúten adequada."}]}}}, {"id": "5823090c-3ccb-4798-8ad7-9ea02c095aa8", "public_path": "/camarones-al-ajillo", "language": "es", "before": {"seo": {"faq": [{"a": "Cuando pasan de grises y translúcidos a un color rosado-blanco opaco y se enroscan ligeramente en forma de \"C\", entre 2 y 3 minutos por lado. Si se enroscan del todo en forma de \"O\" cerrada, ya se pasaron de cocción.", "q": "¿Cómo sé cuándo están listos los camarones?"}, {"a": "Sí, sustitúyelo por caldo de pescado o de pollo con una cucharadita de vinagre blanco o jugo de limón; el resultado es más suave pero igual de sabroso.", "q": "¿Puedo hacer la receta sin vino blanco?"}, {"a": "Lo clásico es con pan crujiente para mojar en la salsa, o con arroz blanco para aprovecharla. También va bien con pasta.", "q": "¿Con qué se sirven los camarones al ajillo?"}, {"a": "Sí, pero descongélalos por completo y sécalos bien con papel de cocina antes de cocinarlos; si están húmedos, sueltan agua en la sartén y en vez de dorarse, se cuecen al vapor.", "q": "¿Puedo usar camarones congelados?"}], "title": "Camarones al ajillo: receta fácil y rápida | Manual de Cocina", "robots": "index,follow", "description": "Camarones salteados con ajo, aceite de oliva, vino blanco y perejil. Un plato español clásico, listo en 20 minutos."}, "notes": "<h3>Consejos</h3>\n<ul>\n<li>El punto exacto de los camarones es 2-3 minutos por lado: se pasan de cocción muy rápido y quedan gomosos. Retíralos en cuanto estén opacos y rosados (el USDA marca 63 °C/145 °F como temperatura interna segura para camarones y otros mariscos).</li>\n<li>Añade el ajo picado solo al final del sofrito de los camarones y por 30 segundos: se quema con facilidad y amarga la salsa si se cocina de más o se pone antes de tiempo.</li>\n<li>Si el vino blanco no reduce en 2-3 minutos, sube un poco el fuego: el objetivo es que se evapore el alcohol y la salsa espese ligeramente, no cocinarlo más tiempo del necesario.</li>\n<li>Añade el jugo de limón al final, fuera del fuego, para que mantenga su acidez fresca; cocinarlo de más le quita brillo al sabor.</li>\n</ul>\n<h3>Sustituciones</h3>\n<ul>\n<li>Vino blanco: caldo de pescado o de pollo con una cucharadita de vinagre blanco o jugo de limón, para mantener la acidez sin alcohol.</li>\n<li>Aceite de oliva: aceite vegetal, aunque se pierde parte del sabor.</li>\n<li>Pimentón: pimentón ahumado o una pizca de ají en polvo si te gusta más picante.</li>\n<li>Camarones: funciona igual con langostinos o colas de camarón congeladas, descongeladas y bien secas antes de cocinar.</li>\n</ul>\n<h3>Conservación</h3>\n<p>Guarda los camarones cocidos en la nevera en un recipiente cerrado hasta 2 días. Recaliéntalos suavemente en una sartén a fuego bajo: el microondas o el fuego fuerte los vuelve gomosos con facilidad. No se recomienda congelar el plato ya preparado, porque el marisco pierde textura al descongelarse; es mejor congelar los camarones crudos y cocinar la receta el mismo día que se van a comer.</p>\n<p class=\"md-sources\">Fuente: <a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-temperature-chart\" rel=\"noopener\" target=\"_blank\">USDA FSIS, temperaturas mínimas seguras</a> (en inglés).</p>"}, "after": {"seo": {"faq": [{"q": "¿Cómo evito que los camarones queden gomosos?", "a": "Sécalos y cocínalos sin amontonarlos. Retíralos cuando la carne esté firme y opaca; si mides la temperatura, busca 63 °C en la parte más gruesa."}, {"q": "¿Puedo preparar la receta sin vino?", "a": "Sí. Usa caldo de pescado o verduras y ajusta la acidez con unas gotas de limón. Una reducción breve del vino no garantiza eliminar todo el alcohol."}, {"q": "¿Sirven los camarones congelados?", "a": "Sí. Descongélalos en la nevera, escúrrelos y sécalos bien antes de saltearlos para que no suelten demasiada agua en la sartén."}], "title": "Camarones al ajillo: receta fácil y rápida | Manual de Cocina", "robots": "index,follow", "description": "Camarones salteados con ajo, aceite de oliva, vino blanco y perejil. Un plato español clásico, listo en 20 minutos."}, "notes": "<h3>Consejos</h3>\n<ul>\n<li>El punto exacto de los camarones es 2-3 minutos por lado: se pasan de cocción muy rápido y quedan gomosos. Retíralos en cuanto estén opacos y rosados (el USDA marca 63 °C/145 °F como temperatura interna segura para camarones y otros mariscos).</li>\n<li>Añade el ajo picado solo al final del sofrito de los camarones y por 30 segundos: se quema con facilidad y amarga la salsa si se cocina de más o se pone antes de tiempo.</li>\n<li>Deja que el vino reduzca sin prolongar la cocción de los camarones. Una reducción breve no elimina necesariamente todo el alcohol; si necesitas evitarlo, usa caldo y unas gotas de limón.</li>\n<li>Añade el jugo de limón al final, fuera del fuego, para que mantenga su acidez fresca; cocinarlo de más le quita brillo al sabor.</li>\n</ul>\n<h3>Sustituciones</h3>\n<ul>\n<li>Vino blanco: caldo de pescado o de pollo con una cucharadita de vinagre blanco o jugo de limón, para mantener la acidez sin alcohol.</li>\n<li>Aceite de oliva: aceite vegetal, aunque se pierde parte del sabor.</li>\n<li>Pimentón: pimentón ahumado o una pizca de ají en polvo si te gusta más picante.</li>\n<li>Camarones: funciona igual con langostinos o colas de camarón congeladas, descongeladas y bien secas antes de cocinar.</li>\n</ul>\n<h3>Conservación</h3>\n<p>Guarda los camarones cocidos en la nevera en un recipiente cerrado hasta 2 días. Recaliéntalos suavemente en una sartén a fuego bajo: el microondas o el fuego fuerte los vuelve gomosos con facilidad. No se recomienda congelar el plato ya preparado, porque el marisco pierde textura al descongelarse; es mejor congelar los camarones crudos y cocinar la receta el mismo día que se van a comer.</p>\n<p class=\"md-sources\">Fuente: <a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-temperature-chart\" rel=\"noopener\" target=\"_blank\">USDA FSIS, temperaturas mínimas seguras</a> (en inglés).</p>"}}, {"id": "83d21534-1ba6-41ad-8e74-e281bf7070a8", "public_path": "/en/shrimp-scampi", "language": "en", "before": {"seo": {"title": "Garlic Shrimp: quick, easy recipe | Manual de Cocina", "robots": "index,follow", "description": "Shrimp sautéed with garlic, olive oil, white wine and parsley. A classic Spanish dish, ready in 20 minutes."}}, "after": {"seo": {"title": "Garlic Shrimp: quick, easy recipe | Manual de Cocina", "robots": "index,follow", "description": "Shrimp sautéed with garlic, olive oil, white wine and parsley. A classic Spanish dish, ready in 20 minutes.", "faq": [{"q": "How do I keep the shrimp from turning rubbery?", "a": "Pat them dry and avoid crowding the pan. Remove them when the flesh is firm and opaque; if checking with a thermometer, aim for 145°F (63°C) in the thickest part."}, {"q": "Can I make the recipe without wine?", "a": "Yes. Use fish or vegetable broth and adjust the acidity with a few drops of lemon juice. A brief wine reduction does not guarantee that all alcohol is removed."}, {"q": "Can I use frozen shrimp?", "a": "Yes. Thaw in the refrigerator, drain and pat dry before sautéing so they do not release too much water into the pan."}]}}}, {"id": "cb27b779-c848-4fb5-a216-64643837a125", "public_path": "/de/shrimps-scampi", "language": "de", "before": {"seo": {"title": "Knoblauch-Garnelen: schnelles, einfaches Rezept | Manual de Cocina", "robots": "index,follow", "description": "Garnelen mit Knoblauch, Olivenöl, Weißwein und Petersilie gebraten. Ein spanischer Klassiker, in 20 Minuten fertig."}}, "after": {"seo": {"title": "Knoblauch-Garnelen: schnelles, einfaches Rezept | Manual de Cocina", "robots": "index,follow", "description": "Garnelen mit Knoblauch, Olivenöl, Weißwein und Petersilie gebraten. Ein spanischer Klassiker, in 20 Minuten fertig.", "faq": [{"q": "Wie verhindere ich zähe Garnelen?", "a": "Tupfe sie trocken und überfülle die Pfanne nicht. Nimm sie heraus, sobald das Fleisch fest und undurchsichtig ist; bei einer Messung sollte die dickste Stelle 63 °C erreichen."}, {"q": "Kann ich das Rezept ohne Wein zubereiten?", "a": "Ja. Verwende Fisch- oder Gemüsebrühe und passe die Säure mit etwas Zitronensaft an. Kurzes Einkochen entfernt den Alkohol aus Wein nicht garantiert vollständig."}, {"q": "Kann ich tiefgekühlte Garnelen verwenden?", "a": "Ja. Taue sie im Kühlschrank auf, lasse sie abtropfen und tupfe sie vor dem Braten trocken, damit nicht zu viel Wasser in die Pfanne gelangt."}]}}}, {"id": "4a19ee79-89ac-4203-9a92-9bbb003c5ad7", "public_path": "/fr/crevettes-a-lail", "language": "fr", "before": {"seo": {"title": "Crevettes à l'ail : recette rapide et facile | Manual de Cocina", "robots": "index,follow", "description": "Crevettes sautées à l'ail, à l'huile d'olive, au vin blanc et au persil. Un classique espagnol, prêt en 20 minutes."}}, "after": {"seo": {"title": "Crevettes à l'ail : recette rapide et facile | Manual de Cocina", "robots": "index,follow", "description": "Crevettes sautées à l'ail, à l'huile d'olive, au vin blanc et au persil. Un classique espagnol, prêt en 20 minutes.", "faq": [{"q": "Comment éviter des crevettes caoutchouteuses ?", "a": "Épongez-les et ne surchargez pas la poêle. Retirez-les quand leur chair est ferme et opaque ; si vous mesurez, visez 63 °C dans la partie la plus épaisse."}, {"q": "Peut-on cuisiner cette recette sans vin ?", "a": "Oui. Utilisez du bouillon de poisson ou de légumes et ajustez l'acidité avec quelques gouttes de citron. Une réduction courte du vin ne garantit pas l'élimination de tout l'alcool."}, {"q": "Peut-on utiliser des crevettes surgelées ?", "a": "Oui. Décongelez-les au réfrigérateur, égouttez-les et épongez-les avant de les faire sauter, afin qu'elles ne rendent pas trop d'eau."}]}}}, {"id": "f7150793-aba3-4d74-9983-4a6f2c88148f", "public_path": "/it/gamberetti-allaglio", "language": "it", "before": {"seo": {"title": "Gamberi all'aglio: ricetta facile e veloce | Manual de Cocina", "robots": "index,follow", "description": "Gamberi saltati con aglio, olio d'oliva, vino bianco e prezzemolo. Un classico spagnolo, pronto in 20 minuti."}}, "after": {"seo": {"title": "Gamberi all'aglio: ricetta facile e veloce | Manual de Cocina", "robots": "index,follow", "description": "Gamberi saltati con aglio, olio d'oliva, vino bianco e prezzemolo. Un classico spagnolo, pronto in 20 minuti.", "faq": [{"q": "Come evito gamberi gommosi?", "a": "Asciugali e non affollare la padella. Toglili quando la carne è soda e opaca; se usi un termometro, cerca 63 °C nella parte più spessa."}, {"q": "Posso preparare la ricetta senza vino?", "a": "Sì. Usa brodo di pesce o vegetale e regola l'acidità con poche gocce di limone. Una breve riduzione del vino non garantisce l'eliminazione di tutto l'alcol."}, {"q": "Posso usare gamberi surgelati?", "a": "Sì. Scongelali in frigorifero, scolali e asciugali prima di saltarli, così non rilasciano troppa acqua in padella."}]}}}, {"id": "fa0ce64a-809e-46ab-bb4d-cc91229a25c5", "public_path": "/ja/shurinpu-arugaarikku", "language": "ja", "before": {"seo": {"title": "エビのガーリックオイル炒め：簡単で早いレシピ | Manual de Cocina", "robots": "index,follow", "description": "にんにく、オリーブオイル、白ワイン、パセリで仕上げたエビ料理。スペインの定番、20分で完成。"}}, "after": {"seo": {"title": "エビのガーリックオイル炒め：簡単で早いレシピ | Manual de Cocina", "robots": "index,follow", "description": "にんにく、オリーブオイル、白ワイン、パセリで仕上げたエビ料理。スペインの定番、20分で完成。", "faq": [{"q": "えびが硬くならないコツは？", "a": "水気を拭き、フライパンに詰め込みすぎないようにします。身が締まって不透明になったら取り出し、温度計を使う場合は厚い部分で63°Cを確認します。"}, {"q": "ワインなしでも作れますか？", "a": "はい。魚または野菜のスープに替え、レモン汁を数滴加えて酸味を調整します。ワインを短時間煮詰めても、アルコールがすべてなくなるとは限りません。"}, {"q": "冷凍えびでも使えますか？", "a": "はい。冷蔵庫で解凍し、水を切ってからよく拭いて炒めます。こうするとフライパンに余分な水分が出にくくなります。"}]}}}, {"id": "a4f71689-a182-4e35-96c7-a490d15d3700", "public_path": "/pt/camarao-ao-alho", "language": "pt", "before": {"seo": {"title": "Camarão ao alho: receita fácil e rápida | Manual de Cocina", "robots": "index,follow", "description": "Camarão refogado com alho, azeite, vinho branco e salsa. Um clássico espanhol, pronto em 20 minutos."}}, "after": {"seo": {"title": "Camarão ao alho: receita fácil e rápida | Manual de Cocina", "robots": "index,follow", "description": "Camarão refogado com alho, azeite, vinho branco e salsa. Um clássico espanhol, pronto em 20 minutos.", "faq": [{"q": "Como evito camarões borrachudos?", "a": "Seque e não amontoe na frigideira. Retire quando a carne estiver firme e opaca; se medir com termômetro, procure 63 °C na parte mais grossa."}, {"q": "Posso preparar sem vinho?", "a": "Sim. Use caldo de peixe ou legumes e ajuste a acidez com gotas de limão. Uma redução breve do vinho não garante eliminar todo o álcool."}, {"q": "Posso usar camarões congelados?", "a": "Sim. Descongele na geladeira, escorra e seque bem antes de saltear para que não soltem água demais na frigideira."}]}}}, {"id": "110414da-a854-578f-aedd-57c071c06edf", "public_path": "/fr/crevettes-a-l-ail", "language": "fr", "before": {"title": "Crevettes à l'ail", "seo": {"faq": [{"a": "Environ 4 minutes au total, 2 minutes de chaque côté, jusqu'à ce qu'elles soient roses. Trop cuites, elles deviennent sèches et caoutchouteuses.", "q": "Combien de temps cuire les crevettes à l'ail ?"}, {"a": "Oui. Les décongeler au réfrigérateur, les égoutter et les éponger très soigneusement avec du papier absorbant avant de les faire sauter.", "q": "Peut-on utiliser des crevettes surgelées ?"}, {"a": "Du pain croustillant pour saucer l'huile et, pour un repas plus complet, du riz blanc ou une salade verte.", "q": "Que servir avec les crevettes à l'ail ?"}], "title": "Crevettes à l'ail, faciles et juteuses | Manual de Cocina", "description": "Crevettes à l'ail avec piment, vin blanc et citron, juteuses et parfumées. Pour 4 personnes, prêtes en 20 minutes. Recette pas à pas.", "image_variants": ["/recetas/langostinos-al-ajillo/portada-1x1.webp", "/recetas/langostinos-al-ajillo/portada-4x3.webp", "/recetas/langostinos-al-ajillo/portada-16x9.webp"]}}, "after": {"title": "Grosses crevettes à l’ail et au citron", "seo": {"faq": [{"a": "Environ 4 minutes au total, 2 minutes de chaque côté, jusqu'à ce qu'elles soient roses. Trop cuites, elles deviennent sèches et caoutchouteuses.", "q": "Combien de temps cuire les crevettes à l'ail ?"}, {"a": "Oui. Les décongeler au réfrigérateur, les égoutter et les éponger très soigneusement avec du papier absorbant avant de les faire sauter.", "q": "Peut-on utiliser des crevettes surgelées ?"}, {"a": "Du pain croustillant pour saucer l'huile et, pour un repas plus complet, du riz blanc ou une salade verte.", "q": "Que servir avec les crevettes à l'ail ?"}], "title": "Grosses crevettes à l’ail, citron et piment", "description": "Crevettes à l'ail avec piment, vin blanc et citron, juteuses et parfumées. Pour 4 personnes, prêtes en 20 minutes. Recette pas à pas.", "image_variants": ["/recetas/langostinos-al-ajillo/portada-1x1.webp", "/recetas/langostinos-al-ajillo/portada-4x3.webp", "/recetas/langostinos-al-ajillo/portada-16x9.webp"]}}}]$quality_data$::jsonb;
  change jsonb;
  current_row jsonb;
  field text;
  already_done boolean;
  changed integer := 0;
begin
  for change in select value from jsonb_array_elements(changes) loop
    select to_jsonb(r) into current_row from public.recipes r where id=(change->>'id')::uuid for update;
    if current_row is null or not (current_row->>'published')::boolean then raise exception 'Missing published record %', change->>'id'; end if;
    already_done := true;
    for field in select jsonb_object_keys(change->'after') loop
      if current_row->field is distinct from change->'after'->field then already_done := false; end if;
    end loop;
    if already_done then continue; end if;
    for field in select jsonb_object_keys(change->'before') loop
      if current_row->field is distinct from change->'before'->field then raise exception 'Concurrent edit to % on %', field, change->>'id'; end if;
    end loop;
    update public.recipes r set
      seo = case when change->'after' ? 'seo' then change->'after'->'seo' else r.seo end,
      notes = case when change->'after' ? 'notes' then change->'after'->>'notes' else r.notes end,
      ingredients = case when change->'after' ? 'ingredients' then change->'after'->'ingredients' else r.ingredients end,
      title = case when change->'after' ? 'title' then change->'after'->>'title' else r.title end
    where id=(change->>'id')::uuid;
    changed := changed + 1;
  end loop;
  -- Remove the unused wheat alternative from the pantry graph and keep positions
  -- aligned with the eleven actual corn-arepa ingredients. Never move unrelated rows.
  if exists(select 1 from public.recipe_ingredients where id='ebf01cb5-a9f1-499d-9f7c-1e5c456e7839' and recipe_id='1f1ab8d4-0e85-4faa-ac4c-96f581cfbe90' and position=1) then
    delete from public.recipe_ingredients where id='ebf01cb5-a9f1-499d-9f7c-1e5c456e7839';
    update public.recipe_ingredients set position=position+1000 where recipe_id='1f1ab8d4-0e85-4faa-ac4c-96f581cfbe90' and position>=2;
    update public.recipe_ingredients set position=position-1001 where recipe_id='1f1ab8d4-0e85-4faa-ac4c-96f581cfbe90' and position>=1002;
  end if;
  raise notice 'QUALITY_EDITORIAL_ROWS_UPDATED=%',changed;
end;
$quality$;
commit;
select language,count(*) filter(where jsonb_array_length(coalesce(seo->'faq','[]'::jsonb))=0) as missing_faq,count(*) as published from public.recipes where published group by language order by language;
